    const silMat = new THREE.MeshLambertMaterial({ color: 0x1f3a25, emissive: 0x112a18, emissiveIntensity: .8 });
    this.addBoxMesh(.42, .65, .3, silMat, 0, .2, 0, 0, sil);
    this.addBoxMesh(.3, .28, .26, silMat, 0, .67, .02, 0, sil);
    for (const s of [-1, 1]) {
