input.content:
import * as THREE from 'three';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const damp = (a, b, lambda, dt) => a + (b - a) * (1 - Math.exp(-lambda * dt));
const wrapAngle = a => ((a + Math.PI * 3) % (Math.PI * 2)) - Math.PI;

function box(w, h, d, mat, x, y, z) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.castShadow = true; m.receiveShadow = true;
  return m;
}

export class Monster {
  constructor(scene, world, spawn = { x: 112, z: 88 }) {
    this.scene = scene;
    this.world = world;
    this.pos = new THREE.Vector3(spawn.x, world.groundAt(spawn.x, spawn.z), spawn.z);
    this.yaw = -2.2;
    this.radius = 0.95;
    this.speed = 0;
    this.maxSpeed = 33 / 3.6; // 9.17 m/s
    this.state = 'wander';
    this.stateTime = 0;
    this.lastHeard = new THREE.Vector3().copy(this.pos);
    this.lastHeardAge = 99;
    this.searchTimer = 0;
    this.attackCd = 0;
    this.roarCd = 6;
    this.stepTravel = 0;
    this.stuck = 0;
    this.wanderTimer = 0;
    this.wanderTarget = this.pickWanderTarget();
    this.attackAnim = 0;
    this.attackAnimTime = 0;
    this.huntingAnnounced = false;
    this.distanceToPlayer = 999;
    this.threat = 0;
    this.pan = 0;
    this.enraged = false;
    this.phase = Math.random() * 10;
    this.trailTimer = 0;
    this.breathTimer = 0;
    this.buildModel();
  }

  buildModel() {
    const base = new THREE.MeshLambertMaterial({ color: 0x3f5c2b, flatShading: true, emissive: 0x071006 });
    const base2 = new THREE.MeshLambertMaterial({ color: 0x4d6d31, flatShading: true, emissive: 0x060d05 });
    const dark = new THREE.MeshLambertMaterial({ color: 0x1a331b, flatShading: true });
    const stripe = new THREE.MeshLambertMaterial({ color: 0x173a1b, flatShading: true, emissive: 0x020803 });
    const belly = new THREE.MeshLambertMaterial({ color: 0x6d8342, flatShading: true });
    const skin = new THREE.MeshLambertMaterial({ color: 0x4b5931, flatShading: true });
    const mouthMat = new THREE.MeshBasicMaterial({ color: 0x190504 });
    const toothMat = new THREE.MeshLambertMaterial({ color: 0xc6bd95, flatShading: true });
    const eyeSocket = new THREE.MeshBasicMaterial({ color: 0x081107 });
    this.mats = { base, base2, dark, stripe, belly, skin };

    const model = new THREE.Group();
    this.model = model;
    this.scene.add(model);

    const body = new THREE.Group();
    body.position.y = 1.52;
    model.add(body);
    this.body = body;
    const torso = box(1.32, 1.22, 0.86, base, 0, 0.16, 0);
    body.add(torso);
    // massive shoulders
    const shoulders = box(1.62, 0.44, 0.92, base2, 0, 0.62, 0);
    body.add(shoulders);
    const chest = box(0.84, 0.6, 0.12, belly, 0, 0.12, 0.44);
    body.add(chest);
    // moss stripes wrapping torso
    for (let i = 0; i < 7; i++) {
      const s = box(0.95 + Math.random() * 0.35, 0.1 + Math.random() * 0.12, 0.9, stripe, (Math.random() - .5) * .2, .6 - i * .2, 0);
      s.scale.x = 1.02 + Math.random() * 0.05;
      body.add(s);
    }
    // moss clumps
    for (let i = 0; i < 16; i++) {
      const c = box(0.08 + Math.random() * .16, 0.06 + Math.random() * .12, 0.08 + Math.random() * .14, base2,
        (Math.random() - .5) * 1.2, (Math.random() - .5) * 1.1, .44 + Math.random() * .05);
      body.add(c);
    }
    // spine ridge
    for (let i = 0; i < 5; i++) {
      const sp = box(0.14, 0.24 + i * .03, 0.18, dark, 0, 0.72 - i * .24, -0.46);
      body.add(sp);
    }

    const head = new THREE.Group();
    head.position.set(0, 0.92, 0.12);
    body.add(head);
    this.head = head;
    const skull = box(0.78, 0.6, 0.68, base, 0, 0.1, 0);
    head.add(skull);
    const crown = box(0.84, 0.2, 0.7, base2, 0, 0.4, -0.02);
    head.add(crown);
    // eyeless pits
    for (const s of [-1, 1]) {
      const pit = box(0.18, 0.12, 0.035, eyeSocket, s * 0.2, 0.22, 0.345);
      head.add(pit);
      const ridge = box(0.26, 0.07, 0.07, stripe, s * 0.2, 0.32, 0.34);
      head.add(ridge);
      const cheek = box(0.2, 0.3, 0.1, skin, s * 0.32, -0.05, 0.34);
      head.add(cheek);
    }
    const muzzle = box(0.52, 0.25, 0.2, skin, 0, -0.16, 0.37);
    head.add(muzzle);
    const mouthPivot = new THREE.Group();
    mouthPivot.position.set(0, -0.19, 0.46);
    head.add(mouthPivot);
    this.mouthPivot = mouthPivot;
    const mouth = box(0.58, 0.15, 0.09, mouthMat, 0, -0.04, 0);
    mouthPivot.add(mouth);
    this.mouth = mouth;
    for (let i = 0; i < 8; i++) {
      const tooth = box(0.05, 0.07, 0.04, toothMat, -0.24 + i * 0.068, 0.015, 0.055);
      mouthPivot.add(tooth);
    }
    for (let i = 0; i < 7; i++) {
      const tooth = box(0.045, 0.06, 0.035, toothMat, -0.2 + i * 0.067, -0.105, 0.06);
      mouthPivot.add(tooth);
    }
    // jaw lower
    const jaw = box(0.54, 0.14, 0.16, skin, 0, -0.15, 0.04);
    mouthPivot.add(jaw);
    this.jaw = jaw;

    const makeArm = side => {
      const shoulder = new THREE.Group();
      shoulder.position.set(side * 0.88, 0.55, 0);
      body.add(shoulder);
      const upper = box(0.38, 0.9, 0.42, base, 0, -0.42, 0);
      shoulder.add(upper);
      const elbow = new THREE.Group();
      elbow.position.y = -0.86;
      shoulder.add(elbow);
      const fore = box(0.32, 0.85, 0.36, base2, 0, -0.4, 0);
      elbow.add(fore);
      const hand = box(0.38, 0.4, 0.45, skin, 0, -0.92, 0.03);
      elbow.add(hand);
      for (let i = 0; i < 4; i++) {
        const finger = box(0.07, 0.3, 0.1, skin, -0.13 + i * 0.09, -1.16, 0.1);
        elbow.add(finger);
      }
      // moss stripes on arm
      for (let i = 0; i < 4; i++) {
        const st = box(0.4, 0.07, 0.44, stripe, 0, -0.2 - i * 0.22, 0);
        shoulder.add(st);
      }
      for (let i = 0; i < 5; i++) {
        const m = box(0.1, 0.09, 0.08, base2, (Math.random() - .5) * .25, -Math.random() * .85, .18 + Math.random() * .06);
        shoulder.add(m);
      }
      return { shoulder, elbow };
    };
    this.armL = makeArm(-1);
    this.armR = makeArm(1);

    const makeLeg = side => {
      const hip = new THREE.Group();
      hip.position.set(side * 0.38, 1.26, 0);
      model.add(hip);
      const thigh = box(0.46, 0.82, 0.5, base, 0, -0.35, 0);
      hip.add(thigh);
      const knee = new THREE.Group();
      knee.position.y = -0.76;
      hip.add(knee);
      const shin = box(0.36, 0.7, 0.38, base2, 0, -0.32, 0);
      knee.add(shin);
      const foot = box(0.44, 0.22, 0.68, skin, 0, -0.68, 0.14);
      knee.add(foot);
      for (let i = 0; i < 3; i++) {
        const toe = box(0.1, 0.09, 0.16, skin, -0.13 + i * 0.13, -0.72, 0.5);
        knee.add(toe);
      }
      return { hip, knee };
    };
    this.legL = makeLeg(-1);
    this.legR = makeLeg(1);

    // hanging moss vines
    this.vines = [];
    for (let i = 0; i < 8; i++) {
      const v = box(0.035, 0.4 + Math.random() * .6, 0.035, base2, (Math.random() - .5) * 1.4, 0.2 + Math.random() * .4, -0.45);
      body.add(v); this.vines.push(v);
    }

    // faint green bio-glow to read in the dark
    const glow = new THREE.PointLight(0x62b24a, 2.2, 5, 2);
    glow.position.set(0, 1.8, 0.2);
    model.add(glow);
    this.glow = glow;

    // flies around the head
    const flyCount = 10;
    const geo = new THREE.BufferGeometry();
    const arr = new Float32Array(flyCount * 3);
    geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    this.flyGeo = geo;
    this.flyBase = [];
    for (let i = 0; i < flyCount; i++) this.flyBase.push({ a: Math.random() * 6.28, r: .5 + Math.random() * 1.1, y: 1.7 + Math.random() * 1.4, s: .4 + Math.random() * 1.2 });
    this.flies = new THREE.Points(geo, new THREE.PointsMaterial({ color: 0xc6e58a, size: .09, transparent: true, opacity: .7, depthWrite: false, blending: THREE.AdditiveBlending }));
    this.scene.add(this.flies);

    model.position.copy(this.pos);
    model.rotation.y = this.yaw;
  }

  pickWanderTarget(anchor = this.pos) {
    const a = Math.random() * Math.PI * 2;
    const r = 18 + Math.random() * 70;
    const x = clamp(anchor.x + Math.cos(a) * r, -235, 235);
    const z = clamp(anchor.z + Math.sin(a) * r, -235, 235);
    return new THREE.Vector3(x, 0, z);
  }

  hear(pos, strength, game, predelay = 0) {
    const spread = 3 + (1 - strength) * 11;
    this.lastHeard.set(
      pos.x + (Math.random() - .5) * spread,
      0,
      pos.z + (Math.random() - .5) * spread
    );
    this.lastHeardAge = 0;
    if (this.state !== 'hunt') {
      this.state = 'hunt';
      this.stateTime = 0;
      if (game) {
        const dist = this.pos.distanceTo(pos);
        if (dist < 95) this.roar(game, dist);
        if (dist < 110) game.onMonsterAlert?.();
      }
    }
  }

  roar(game, dist = 30) {
    if (!game || this.roarCd > 0) return;
    this.roarCd = 7 + Math.random() * 5;
    const pan = this.pan;
    const vol = clamp(1.25 - dist / 150, .18, 1);
    game.audio.monsterRoar(pan, vol);
    game.onMonsterRoar?.(dist);
  }

  update(dt, time, player, game) {
    if (player.dead) { this.updateModel(dt, 0); return; }
    const toPlayer = new THREE.Vector3(player.pos.x - this.pos.x, 0, player.pos.z - this.pos.z);
    const dist = toPlayer.length();
    this.distanceToPlayer = dist;
    const dirToPlayer = Math.atan2(toPlayer.x, toPlayer.z);
    this.pan = Math.sin(wrapAngle(dirToPlayer - player.yaw));

    this.attackCd = Math.max(0, this.attackCd - dt);
    this.roarCd = Math.max(0, this.roarCd - dt);
    this.lastHeardAge += dt;
    this.stateTime += dt;
    this.attackAnim = Math.max(0, this.attackAnim - dt);

    // acoustic detection from continuous player noise
    const noiseRange = (this.enraged ? 10 : 8) + (this.enraged ? 76 : 62) * player.noise;
    if (player.noise > 0.06 && dist < noiseRange) {
      this.hear(player.pos, player.noise, game);
    }
    // discrete noise events (doors, rocks, cores)
    if (game?.noiseEvents) {
      for (const ev of game.noiseEvents) {
        if (ev.heard || ev.age > 2.4) continue;
        const d = Math.hypot(ev.pos.x - this.pos.x, ev.pos.z - this.pos.z);
        if (d < 18 + 118 * ev.strength) {
          ev.heard = true;
          this.hear(ev.pos, ev.strength, game);
        }
      }
    }
    // near breathing detection, even when still
    if (dist < (player.crouchBlend > .5 ? 5.5 : 3.1) + (this.enraged ? 3 : 0) && player.health > 0) {
      this.lastHeard.copy(player.pos);
      this.lastHeardAge = 0;
      if (this.state !== 'hunt') {
        this.state = 'hunt'; this.stateTime = 0;
        if (game) { this.roar(game, dist); game.onMonsterAlert?.(); }
      }
    }

    if (this.state === 'hunt') {
      if (this.lastHeardAge < 1.15) {
        // pursue predicted player position with slight auditory error
        this.lastHeard.lerp(new THREE.Vector3(player.pos.x, 0, player.pos.z), Math.min(1, dt * (this.enraged ? 4.2 : 2.8)));
      } else {
        this.state = 'search';
        this.stateTime = 0;
        this.searchTimer = 7 + Math.random() * 4;
      }
    } else if (this.state === 'search') {
      this.searchTimer -= dt;
      if (this.searchTimer <= 0 || this.lastHeardAge > 14) {
        this.state = 'wander';
        this.stateTime = 0;
        this.wanderTimer = 0;
        this.wanderTarget = this.pickWanderTarget(this.pos);
      }
    } else {
      // wander
      this.wanderTimer -= dt;
      const dTarget = Math.hypot(this.wanderTarget.x - this.pos.x, this.wanderTarget.z - this.pos.z);
      if (dTarget < 4 || this.wanderTimer <= 0) {
        this.wanderTarget = this.pickWanderTarget(this.pos);
        this.wanderTimer = 11 + Math.random() * 16;
      }
    }

    // choose a movement target
    let target = this.wanderTarget;
    let desiredSpeed = 1.9;
    if (this.state === 'hunt') {
      target = this.lastHeard;
      desiredSpeed = this.maxSpeed;
      if (this.lastHeardAge > 2.5) desiredSpeed = this.maxSpeed * .55;
    } else if (this.state === 'search') {
      target = this.lastHeard;
      const dT = Math.hypot(target.x - this.pos.x, target.z - this.pos.z);
      if (dT < 3.5) {
        // circle / sniff around the last heard point
        const ang = time * .7 + this.phase;
        target = new THREE.Vector3(this.lastHeard.x + Math.cos(ang) * 4.5, 0, this.lastHeard.z + Math.sin(ang) * 4.5);
        desiredSpeed = 2.2;
      } else desiredSpeed = 4.2;
    }

    const dx = target.x - this.pos.x, dz = target.z - this.pos.z;
    const targetYaw = Math.atan2(dx, dz);
    const diff = wrapAngle(targetYaw - this.yaw);
    const speedRatio = clamp(this.speed / this.maxSpeed, 0, 1);
    // 50% turning resistance: high speed = wide sweeps
    const turnRate = (1.85 - speedRatio * 1.23) * (this.enraged ? 1.08 : 1);
    this.yaw += clamp(diff, -turnRate * dt, turnRate * dt);
    // slow down to turn
    if (Math.abs(diff) > 1.2 && this.speed > 4) desiredSpeed *= .55;

    this.speed = damp(this.speed, desiredSpeed, desiredSpeed > this.speed ? 2.2 : 4.5, dt);
    const step = this.speed * dt;
    const prevX = this.pos.x, prevZ = this.pos.z;
    this.pos.x += Math.sin(this.yaw) * step;
    this.pos.z += Math.cos(this.yaw) * step;

    // obstacle avoidance by probing ahead
    const probe = new THREE.Vector3(this.pos.x + Math.sin(this.yaw) * (1.4 + this.speed * .18), 0, this.pos.z + Math.cos(this.yaw) * (1.4 + this.speed * .18));
    const test = probe.clone();
    const blocked = this.world.resolveCollisions(test, this.radius);
    if (blocked) {
      const side = Math.sin(time * 2.1 + this.phase) > 0 ? 1 : -1;
      this.yaw += side * 1.9 * dt;
      this.pos.x -= Math.sin(this.yaw) * step * .2;
      this.pos.z -= Math.cos(this.yaw) * step * .2;
    }
    this.world.resolveCollisions(this.pos, this.radius);
    const actual = Math.hypot(this.pos.x - prevX, this.pos.z - prevZ);
    if (actual < step * .18) {
      this.stuck += dt;
      if (this.stuck > 1.2) {
        this.yaw += (Math.random() - .5) * 2.2;
        if (this.state === 'hunt') {
          this.state = 'search'; this.searchTimer = 5; this.stateTime = 0;
          this.stuck = 0;
        }
      }
    } else this.stuck = Math.max(0, this.stuck - dt * 2);
    this.pos.y = damp(this.pos.y, this.world.groundAt(this.pos.x, this.pos.z), 12, dt);

    // attack
    const facingPlayer = Math.abs(wrapAngle(dirToPlayer - this.yaw)) < .82;
    if (dist < 3.7 && this.attackCd <= 0 && facingPlayer && this.state !== 'wander') {
      this.attackCd = 2.5;
      this.attackAnim = .8;
      if (game) {
        game.audio.monsterRoar(this.pan, 1.2);
        player.takeDamage(46, this.pos, game);
        game.effects?.impact(new THREE.Vector3(player.pos.x, player.pos.y + 1.2, player.pos.z), 0x9b2a14, 18);
      }
    }

    // footfalls
    this.stepTravel += actual;
    const stride = this.speed > 5 ? 1.65 : 2.2;
    if (this.stepTravel > stride) {
      this.stepTravel = 0;
      if (game && dist < 55) game.audio.monsterStep(clamp(.3 - dist / 220, .02, .2), this.pan);
      if (game && dist < 80) game.effects?.dust(new THREE.Vector3(this.pos.x, this.pos.y + .1, this.pos.z), 3);
    }

    // spore trail
    this.trailTimer -= dt;
    if (this.trailTimer <= 0) {
      this.trailTimer = .35 + Math.random() * .4;
      if (game && dist < 75) game.effects?.spore(this.pos, this.yaw);
    }

    // ambient roars / breath
    if (this.state === 'hunt' && this.roarCd <= 0 && dist < 45) this.roar(game, dist);
    if (this.state === 'wander' && this.roarCd <= 0 && dist < 70 && Math.random() < dt * .05) this.roar(game, dist);
    this.breathTimer -= dt;
    if (dist < 14 && this.breathTimer <= 0) {
      this.breathTimer = 2.6 + Math.random() * 2;
      if (game) game.audio._noise({ dur: .6, gain: clamp(.03 - dist / 700, .004, .025), type: 'bandpass', freq: 320, endFreq: 120, q: 1.4, pan: this.pan });
    }

    // threat for HUD
    const threatRange = this.state === 'hunt' ? 68 : 25;
    this.threat = clamp(1 - dist / threatRange, 0, 1);
    if (this.state === 'hunt') this.threat = clamp(this.threat + .22, 0, 1);
    if (dist < 4) this.threat = 1;

    this.updateModel(dt, actual / Math.max(dt, .001));
    this.model.position.copy(this.pos);
    this.model.rotation.y = this.yaw;

    // flies
    const arr = this.flyGeo.attributes.position.array;
    for (let i = 0; i < this.flyBase.length; i++) {
      const b = this.flyBase[i];
      const a = b.a + time * b.s;
      arr[i * 3] = Math.cos(a) * b.r;
      arr[i * 3 + 1] = b.y + Math.sin(time * 2 + b.a) * .3;
      arr[i * 3 + 2] = Math.sin(a) * b.r;
    }
    this.flyGeo.attributes.position.needsUpdate = true;
    this.flies.position.copy(this.pos);
    this.glow.intensity = this.state === 'hunt' ? 3.0 : 1.8 + Math.sin(time * 1.4) * .3;
  }

  updateModel(dt, movedSpeed) {
    const t = performance.now() * .001;
    const walking = this.speed > .15;
    const run = clamp(this.speed / this.maxSpeed, 0, 1);
    const breathing = Math.sin(t * 1.6 + this.phase) * .02;
    const charge = this.state === 'hunt' ? clamp(run, 0, 1) : 0;
    const phase = t * (3.2 + run * 7.5) + this.phase;

    this.body.position.y = 1.52 - charge * .28 + (walking ? Math.abs(Math.sin(phase)) * .045 : 0);
    this.body.rotation.x = charge * .55 + (walking ? Math.sin(phase * 2) * .02 : breathing);
    this.body.rotation.z = walking ? Math.sin(phase) * .035 * (1 - charge * .4) : breathing;

    const swing = Math.sin(phase) * (walking ? (.34 + run * .52) : .015);
    const armBase = -0.12 + charge * 0.66;
    this.armL.shoulder.rotation.x = -swing + armBase;
    this.armR.shoulder.rotation.x = swing + armBase;
    this.armL.shoulder.rotation.z = -0.16 - charge * .12;
    this.armR.shoulder.rotation.z = 0.16 + charge * .12;
    this.armL.elbow.rotation.x = -0.25 - charge * .4 - Math.max(0, swing) * .45;
    this.armR.elbow.rotation.x = -0.25 - charge * .4 - Math.max(0, -swing) * .45;

    // attack smear
    if (this.attackAnim > 0) {
      const p = 1 - this.attackAnim / .8;
      const swipe = Math.sin(p * Math.PI);
      this.armR.shoulder.rotation.x = -1.8 + p * 3.2;
      this.armR.shoulder.rotation.z = .2 + swipe * .9;
      this.armL.shoulder.rotation.x = -1.2 + p * 2.2;
    }

    this.legL.hip.rotation.x = swing * .88 + charge * .2;
    this.legR.hip.rotation.x = -swing * .88 + charge * .2;
    this.legL.knee.rotation.x = Math.max(0, -swing) * 1.0 + charge * .25;
    this.legR.knee.rotation.x = Math.max(0, swing) * 1.0 + charge * .25;

    this.head.rotation.x = -charge * .32 + Math.sin(t * .9) * .02;
    this.head.rotation.y = this.state === 'search' ? Math.sin(t * .95) * .55 : Math.sin(t * .35) * .07;
    this.head.rotation.z = Math.sin(t * .5) * .02;

    // mouth widens when hunting/attacking
    const open = .55 + charge * .7 + (this.attackAnim > 0 ? Math.sin((1 - this.attackAnim / .8) * Math.PI) * .8 : 0) + Math.sin(t * 2.4 + this.phase) * .08;
    this.mouth.scale.y = 1 + open;
    this.jaw.position.y = -0.15 - open * .09;
    this.jaw.scale.y = 1 + open * .3;

    for (let i = 0; i < this.vines.length; i++) {
      const v = this.vines[i];
      v.rotation.x = Math.sin(t * 1.2 + i) * .12 + charge * .2;
      v.rotation.z = Math.cos(t * .9 + i * 2) * .1;
    }
  }

  getPanForListener(player) {
    const dx = this.pos.x - player.pos.x, dz = this.pos.z - player.pos.z;
    const ang = Math.atan2(dx, dz);
    return Math.sin(wrapAngle(ang - player.yaw));
  }
}

import * as THREE from 'three';
import { glowGreen } from './textures.js';

const MAX = 900;

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.particles = [];
    this.pos = new Float32Array(MAX * 3);
    this.col = new Float32Array(MAX * 3);
    this.geo = new THREE.BufferGeometry();
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage));
    this.geo.setAttribute('color', new THREE.BufferAttribute(this.col, 3).setUsage(THREE.DynamicDrawUsage));
    for (let i = 0; i < MAX; i++) {
      this.pos[i * 3 + 1] = -9999;
      this.particles.push({ active: false, vx: 0, vy: 0, vz: 0, life: 0, max: 1, grav: 0, drag: 1 });
    }
    this.points = new THREE.Points(this.geo, new THREE.PointsMaterial({
      size: .15, sizeAttenuation: true, vertexColors: true, transparent: true, opacity: .95,
      depthWrite: false, blending: THREE.AdditiveBlending,
    }));
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.cursor = 0;

    this.buildRain();
    this.buildMotes();
  }

  buildRain() {
    const count = 780;
    this.rainCount = count;
    this.rainDrops = [];
    const pos = new Float32Array(count * 6);
    this.rainGeo = new THREE.BufferGeometry();
    this.rainGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3).setUsage(THREE.DynamicDrawUsage));
    this.rainMat = new THREE.LineBasicMaterial({ color: 0x91b4ad, transparent: true, opacity: .22, depthWrite: false, fog: true });
    this.rain = new THREE.LineSegments(this.rainGeo, this.rainMat);
    this.rain.frustumCulled = false;
    this.scene.add(this.rain);
    for (let i = 0; i < count; i++) {
      this.rainDrops.push({ x: 0, y: 0, z: 0, speed: 18 + Math.random() * 16, len: .5 + Math.random() * .9 });
    }
    this.rainInit = false;
  }

  buildMotes() {
    const count = 150;
    const pos = new Float32Array(count * 3);
    this.moteBase = [];
    for (let i = 0; i < count; i++) {
      const x = (Math.random() - .5) * 14, y = .3 + Math.random() * 4.6, z = (Math.random() - .5) * 14;
      pos[i * 3] = x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = z;
      this.moteBase.push({ x, y, z, phase: Math.random() * 6.28, speed: .1 + Math.random() * .3 });
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    this.motes = new THREE.Points(geo, new THREE.PointsMaterial({
      map: glowGreen, color: 0xcde7ac, size: .075, transparent: true, opacity: .32,
      depthWrite: false, blending: THREE.AdditiveBlending,
    }));
    this.scene.add(this.motes);
  }

  emit(x, y, z, color, { count = 1, speed = 1, up = 1, spread = 1, life = .8, grav = -1, drag = .96, size } = {}) {
    const c = new THREE.Color(color);
    for (let n = 0; n < count; n++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % MAX;
      const p = this.particles[i];
      p.active = true;
      p.vx = (Math.random() - .5) * speed * spread;
      p.vy = Math.random() * speed * up;
      p.vz = (Math.random() - .5) * speed * spread;
      p.life = life * (.6 + Math.random() * .7);
      p.max = p.life;
      p.grav = grav;
      p.drag = drag;
      this.pos[i * 3] = x + (Math.random() - .5) * .3;
      this.pos[i * 3 + 1] = y + (Math.random() - .5) * .3;
      this.pos[i * 3 + 2] = z + (Math.random() - .5) * .3;
      const jitter = .7 + Math.random() * .5;
      this.col[i * 3] = c.r * jitter;
      this.col[i * 3 + 1] = c.g * jitter;
      this.col[i * 3 + 2] = c.b * jitter;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
  }

  burst(pos, color, count = 30, speed = 2.5) {
    this.emit(pos.x, pos.y, pos.z, color, { count, speed, up: 1.2, spread: 1, life: 1.15, grav: -2.2, drag: .965 });
  }
  impact(pos, color = 0xaa3a22, count = 16) {
    this.emit(pos.x, pos.y, pos.z, color, { count, speed: 2.2, up: .8, spread: 1, life: .55, grav: -6, drag: .94 });
  }
  dust(pos, count = 4) {
    this.emit(pos.x, pos.y + .15, pos.z, 0x5c6249, { count, speed: .45, up: .5, spread: 1.4, life: .9, grav: -.15, drag: .94 });
  }
  spore(pos, yaw) {
    const x = pos.x - Math.sin(yaw) * 1.1 + (Math.random() - .5) * 1.2;
    const z = pos.z - Math.cos(yaw) * 1.1 + (Math.random() - .5) * 1.2;
    this.emit(x, pos.y + .5 + Math.random() * 1.9, z, 0x88c45c, { count: 2, speed: .22, up: .3, spread: 1, life: 1.8, grav: .02, drag: .99 });
  }
  steam(pos, count = 6, color = 0xa8bcac) {
    this.emit(pos.x, pos.y, pos.z, color, { count, speed: .9, up: .8, spread: 1.2, life: 1.2, grav: .18, drag: .97 });
  }
  sparks(pos, color = 0xffc46a, count = 8) {
    this.emit(pos.x, pos.y, pos.z, color, { count, speed: 3.4, up: .7, spread: 1.2, life: .5, grav: -7, drag: .96 });
  }

  update(dt, time, player, indoors) {
    const pos = this.geo.attributes.position.array;
    const col = this.geo.attributes.color.array;
    for (let i = 0; i < MAX; i++) {
      const p = this.particles[i];
      if (!p.active) continue;
      p.life -= dt;
      if (p.life <= 0) { p.active = false; pos[i * 3 + 1] = -9999; continue; }
      const d = Math.pow(p.drag, dt * 60);
      p.vx *= d; p.vz *= d; p.vy = p.vy * d + p.grav * dt;
      pos[i * 3] += p.vx * dt;
      pos[i * 3 + 1] += p.vy * dt;
      pos[i * 3 + 2] += p.vz * dt;
      const a = Math.min(1, p.life / (p.max * .4));
      col[i * 3] *= (0.98 + a * .02);
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;

    // motes
    if (player) {
      const inside = indoors;
      this.motes.visible = inside;
      if (inside) {
        const arr = this.motes.geometry.attributes.position.array;
        for (let i = 0; i < this.moteBase.length; i++) {
          const b = this.moteBase[i];
          arr[i * 3] = b.x + Math.sin(time * b.speed + b.phase) * .42;
          arr[i * 3 + 1] = b.y + Math.sin(time * b.speed * .7 + b.phase * 2) * .22;
          arr[i * 3 + 2] = b.z + Math.cos(time * b.speed * .8 + b.phase) * .42;
        }
        this.motes.geometry.attributes.position.needsUpdate = true;
      }
    }

    // rain
    this.rain.visible = !indoors;
    if (!indoors && player) {
      const arr = this.rainGeo.attributes.position.array;
      if (!this.rainInit) {
        for (const d of this.rainDrops) {
          d.x = player.pos.x + (Math.random() - .5) * 70;
          d.z = player.pos.z + (Math.random() - .5) * 70;
          d.y = player.pos.y + Math.random() * 24;
        }
        this.rainInit = true;
      }
      for (let i = 0; i < this.rainDrops.length; i++) {
        const d = this.rainDrops[i];
        d.y -= d.speed * dt;
        d.x += dt * 2.2;
        if (d.y < player.pos.y - 1 || Math.abs(d.x - player.pos.x) > 38 || Math.abs(d.z - player.pos.z) > 38) {
          d.x = player.pos.x + (Math.random() - .5) * 68;
          d.z = player.pos.z + (Math.random() - .5) * 68;
          d.y = player.pos.y + 16 + Math.random() * 12;
        }
        arr[i * 6] = d.x; arr[i * 6 + 1] = d.y; arr[i * 6 + 2] = d.z;
        arr[i * 6 + 3] = d.x - .04; arr[i * 6 + 4] = d.y - d.len; arr[i * 6 + 5] = d.z;
      }
      this.rainGeo.attributes.position.needsUpdate = true;
    }
  }
}

import * as THREE from 'three';
import { World } from './world.js';
import { Player } from './player.js';
import { Monster } from './monster.js';
import { Effects } from './effects.js';
import { GameAudio } from './audio.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const damp = (a, b, l, dt) => a + (b - a) * (1 - Math.exp(-l * dt));
const wrapDeg = d => ((d + 540) % 360) - 180;
const fmtTime = s => {
  const m = Math.floor(s / 60), ss = Math.floor(s % 60);
  return `${String(m).padStart(2, '0')}:${String(ss).padStart(2, '0')}`;
};

class Game {
  constructor() {
    this.clock = new THREE.Clock();
    this.time = 0;
    this.playTime = 0;
    this.state = 'title';
    this.started = false;
    this.sensitivity = 1;
    this.invertY = false;
    this.locked = false;
    this.dragging = false;
    this.noiseEvents = [];
    this.rocks = [];
    this.coresCollected = 0;
    this.ascentTimer = 0;
    this.shakeAmt = 0;
    this.shakeTime = 0;
    this.flash = 0;
    this.lightningTimer = 10 + Math.random() * 15;
    this.thunderTimer = 0;
    this.introRoar = 26;
    this.monsterAlertTimer = 0;
    this.toastCooldown = 0;
    this.throwCd = 0;
    this.jumpQueued = false;
    this.crouchToggle = false;
    this.touchRun = false;
    this.touchCrouch = false;
    this.joy = { x: 0, y: 0, active: false };
    this.isMobile = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.mobileLayout = this.isMobile || innerWidth < 900;
    this.lastPrompt = null;

    this.dom = this.collectDom();
    this.initRenderer();
    this.initScene();
    this.initCompass();
    this.bindEvents();
    this.updateObjective();
    this.updateHud(true);
    this.dom.loadingVeil.classList.add('done');
    this.renderer.render(this.scene, this.camera);
    window.__APE = this;
    this.animate();
  }

  collectDom() {
    const $ = id => document.getElementById(id);
    return {
      canvas: $('game'),
      start: $('startScreen'), startBtn: $('startBtn'),
      pause: $('pauseScreen'), resumeBtn: $('resumeBtn'), restartBtn: $('restartBtn'),
      note: $('noteScreen'), noteKicker: $('noteKicker'), noteTitle: $('noteTitle'), noteBody: $('noteBody'), noteClose: $('noteClose'), noteIndex: $('noteIndex'),
      death: $('deathScreen'), deathStats: $('deathStats'), retryBtn: $('retryBtn'),
      win: $('winScreen'), winStats: $('winStats'), againBtn: $('againBtn'),
      hud: $('hud'), objectiveTitle: $('objectiveTitle'), objectiveDetail: $('objectiveDetail'),
      corePips: Array.from(document.querySelectorAll('#corePips .pip')),
      trackerLabel: $('trackerLabel'), trackerDist: $('trackerDist'), trackerBearing: $('trackerBearing'),
      compassTape: $('compassTape'), compassCaret: $('compassCaret'),
      healthFill: $('healthFill'), healthNum: $('healthNum'), staminaFill: $('staminaFill'), staminaNum: $('staminaNum'),
      lampIcon: $('lampIcon'), lampText: $('lampText'),
      noisePips: Array.from(document.querySelectorAll('#noisePips i')),
      threatCard: $('threatCard'), threatBars: Array.from(document.querySelectorAll('#threatBars i')), threatWord: $('threatWord'),
      prompt: $('prompt'), promptLabel: $('promptLabel'),
      toasts: $('toasts'), monsterBanner: $('monsterBanner'), monsterBannerText: $('monsterBannerText'),
      crosshair: $('crosshair'), reticleHint: $('reticleHint'),
      damage: $('damageFlash'), white: $('whiteFlash'),
      mobile: $('mobileControls'), joystick: $('joystick'), stick: $('stick'), lookPad: $('lookPad'),
      touchInteract: $('touchInteract'), touchJump: $('touchJump'), touchCrouch: $('touchCrouch'),
      touchRun: $('touchRun'), touchView: $('touchView'), touchThrow: $('touchThrow'), touchLamp: $('touchLamp'),
      pauseBtn: $('pauseBtn'), muteBtn: $('muteBtn'), pauseMute: $('pauseMute'), sensitivity: $('sensitivity'),
      invertY: $('invertY'), viewMode: $('viewMode'), lockHint: $('lockHint'), loadingVeil: $('loadingVeil'),
    };
  }

  initRenderer() {
    const renderer = new THREE.WebGLRenderer({ canvas: this.dom.canvas, antialias: false, powerPreference: 'high-performance', stencil: false });
    renderer.setClearColor(0x050908, 1);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer = renderer;
    this.resize();
  }

  resize() {
    const w = innerWidth, h = innerHeight;
    this.mobileLayout = this.isMobile || w < 900;
    const ratio = Math.min(devicePixelRatio || 1, this.mobileLayout ? 1.25 : 1.2);
    const scale = this.mobileLayout ? .82 : .62;
    this.renderer.setPixelRatio(ratio * scale);
    this.renderer.setSize(w, h, false);
    if (this.camera) {
      this.camera.aspect = w / h;
      this.camera.updateProjectionMatrix();
    }
  }

  initScene() {
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(70, innerWidth / innerHeight, .06, 620);
    this.camera.position.set(0, 2.8, 6);
    this.world = new World(this.scene);
    this.player = new Player(this.scene, this.world);
    this.monster = new Monster(this.scene, this.world, { x: 116, z: 92 });
    this.effects = new Effects(this.scene);
    this.audio = new GameAudio();
    this.raycaster = new THREE.Raycaster();
    this.cameraPos = new THREE.Vector3();
    this.cameraTarget = new THREE.Vector3();
    this.camDir = new THREE.Vector3();
  }

  initCompass() {
    const tape = this.dom.compassTape;
    tape.innerHTML = '';
    this.compassTicks = [];
    for (let a = 0; a < 360; a += 15) {
      const t = document.createElement('div');
      t.className = 'compass-tick' + (a % 45 === 0 ? ' major' : '');
      tape.appendChild(t);
      this.compassTicks.push({ el: t, bearing: a });
    }
    const cards = [['N', 0], ['E', 90], ['S', 180], ['W', 270]];
    this.compassCards = cards.map(([label, bearing]) => {
      const el = document.createElement('div');
      el.className = 'compass-card' + (label === 'N' ? ' n' : '');
      el.textContent = label;
      tape.appendChild(el);
      return { el, bearing };
    });
    this.objMark = document.createElement('div');
    this.objMark.className = 'compass-mark';
    tape.appendChild(this.objMark);
    this.homeMark = document.createElement('div');
    this.homeMark.className = 'compass-mark lab';
    tape.appendChild(this.homeMark);
  }

  /* ---------------------------------------------------------------- */
  bindEvents() {
    const canvas = this.dom.canvas;
    addEventListener('resize', () => this.resize());
    addEventListener('contextmenu', e => e.preventDefault());

    this.dom.startBtn.addEventListener('click', () => this.startGame());
    this.dom.resumeBtn.addEventListener('click', () => this.resumeGame());
    this.dom.restartBtn.addEventListener('click', () => location.reload());
    this.dom.retryBtn.addEventListener('click', () => location.reload());
    this.dom.againBtn.addEventListener('click', () => location.reload());
    this.dom.noteClose.addEventListener('click', () => this.closeNote());
    this.dom.pauseBtn.addEventListener('click', () => this.pauseGame());
    this.dom.muteBtn.addEventListener('click', () => this.toggleMute());
    this.dom.pauseMute.addEventListener('click', () => this.toggleMute());
    this.dom.sensitivity.addEventListener('input', () => { this.sensitivity = Number(this.dom.sensitivity.value); });
    this.dom.invertY.addEventListener('click', () => {
      this.invertY = !this.invertY;
      this.dom.invertY.textContent = this.invertY ? 'ON' : 'OFF';
      this.dom.invertY.classList.toggle('on', this.invertY);
    });
    this.dom.viewMode.addEventListener('click', () => this.toggleView());

    canvas.addEventListener('click', () => {
      if (this.state === 'playing' && !this.isMobile && document.pointerLockElement !== canvas) {
        this.requestLock();
      }
    });
    canvas.addEventListener('mousedown', e => {
      if (e.button === 0) this.dragging = true;
    });
    addEventListener('mouseup', () => { this.dragging = false; });
    addEventListener('mousemove', e => {
      if (this.state !== 'playing') return;
      const locked = document.pointerLockElement === canvas;
      if (!locked && !this.dragging) return;
      const mx = e.movementX || 0, my = e.movementY || 0;
      this.applyLook(mx, my, locked ? 1 : .85);
    });
    document.addEventListener('pointerlockchange', () => {
      this.locked = document.pointerLockElement === canvas;
      this.updateLockHint();
    });
    document.addEventListener('pointerlockerror', () => { this.locked = false; this.updateLockHint(); });

    addEventListener('keydown', e => this.onKeyDown(e));
    addEventListener('keyup', e => this.onKeyUp(e));
    addEventListener('blur', () => { if (this.state === 'playing') this.pauseGame(); });

    this.setupTouch();
  }

  requestLock() {
    try {
      const p = this.dom.canvas.requestPointerLock?.();
      if (p?.catch) p.catch(() => {});
    } catch { /* pointer lock can be denied in embedded contexts */ }
  }

  updateLockHint() {
    const show = this.state === 'playing' && !this.locked && !this.isMobile;
    this.dom.lockHint.classList.toggle('hidden', !show);
  }

  startGame() {
    if (this.started) return;
    this.started = true;
    this.state = 'playing';
    this.audio.init();
    this.audio.resume();
    this.dom.start.classList.add('hidden');
    this.dom.mobile.classList.toggle('hidden', !this.mobileLayout);
    this.dom.hud.style.opacity = '1';
    this.updateLockHint();
    if (!this.isMobile) this.requestLock();
    this.player.setView('third');
    this.dom.viewMode.textContent = 'THIRD PERSON';
    this.toast('DIRECTIVE 01', 'Three isotope cores are active in the jungle. Follow the columns of light.', 'good', 6500);
    setTimeout(() => { if (this.state === 'playing') this.toast('LAB ACCESS', 'Use the switch beside a door. Press E. The exterior release is on the left of every frame.', 'warn', 7000); }, 5200);
    setTimeout(() => { if (this.state === 'playing') this.toast('ACOUSTIC HAZARD', 'Moss.Man is blind. Sprinting is loud. Crouch when you hear it breathe.', 'danger', 7000); }, 11000);
    this.audio.ui();
  }

  pauseGame() {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    this.dom.pause.classList.remove('hidden');
    this.dom.mobile.classList.add('hidden');
    this.audio.setPaused(true);
    if (document.pointerLockElement) document.exitPointerLock?.();
    this.updateLockHint();
    this.audio.ui(false);
  }

  resumeGame() {
    if (this.state !== 'paused') return;
    this.state = 'playing';
    this.dom.pause.classList.add('hidden');
    this.dom.mobile.classList.toggle('hidden', !this.mobileLayout);
    this.audio.setPaused(false);
    this.audio.resume();
    if (!this.isMobile) this.requestLock();
    this.updateLockHint();
    this.audio.ui();
  }

  openNote(note) {
    if (this.state !== 'playing') return;
    this.state = 'note';
    this.dom.noteKicker.textContent = 'RECOVERED DATAPAD';
    this.dom.noteTitle.textContent = note.title;
    this.dom.noteBody.textContent = note.body;
    this.dom.noteIndex.textContent = String(note.id).padStart(2, '0');
    this.dom.note.classList.remove('hidden');
    this.dom.mobile.classList.add('hidden');
    if (document.pointerLockElement) document.exitPointerLock?.();
    this.audio.ui();
  }

  closeNote() {
    if (this.state !== 'note') return;
    this.state = 'playing';
    this.dom.note.classList.add('hidden');
    this.dom.mobile.classList.toggle('hidden', !this.mobileLayout);
    if (!this.isMobile) this.requestLock();
    this.audio.ui();
  }

  onKeyDown(e) {
    if (e.repeat) {
      if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ShiftLeft', 'ShiftRight', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) this.keys.set(e.code, true);
      return;
    }
    this.keys.set(e.code, true);
    if (this.state === 'title' && (e.code === 'Enter' || e.code === 'Space')) { e.preventDefault(); this.startGame(); return; }
    if ((this.state === 'dead' || this.state === 'win') && e.code === 'KeyR') { location.reload(); return; }
    if (this.state === 'note') {
      if (e.code === 'KeyE' || e.code === 'Escape') this.closeNote();
      return;
    }
    if (this.state === 'paused') {
      if (e.code === 'KeyP' || e.code === 'Escape') this.resumeGame();
      return;
    }
    if (this.state !== 'playing') return;
    switch (e.code) {
      case 'KeyE': this.tryInteract(); break;
      case 'KeyQ': this.throwRock(); break;
      case 'KeyF': this.toggleLamp(); break;
      case 'KeyV': this.toggleView(); break;
      case 'KeyC': this.crouchToggle = !this.crouchToggle; this.dom.touchCrouch.classList.toggle('on', this.crouchToggle); break;
      case 'KeyM': this.toggleMute(); break;
      case 'KeyP':
      case 'Escape': this.pauseGame(); break;
      case 'Space': e.preventDefault(); this.jumpQueued = true; break;
      default: break;
    }
  }

  onKeyUp(e) { this.keys.set(e.code, false); }

  applyLook(dx, dy, mult = 1) {
    const s = 0.00225 * this.sensitivity * mult;
    this.player.yaw -= dx * s;
    this.player.pitch += (this.invertY ? 1 : -1) * dy * s;
    this.player.pitch = clamp(this.player.pitch, -1.12, 1.05);
  }

  toggleMute() {
    if (!this.audio.ok && this.audio.ctx) return;
    if (!this.audio.ctx) { this.audio.init(); }
    const muted = this.audio.toggleMute();
    this.dom.muteBtn.textContent = muted ? '×' : '♪';
    this.dom.muteBtn.classList.toggle('off', muted);
    this.dom.pauseMute.textContent = muted ? 'OFF' : 'ON';
    this.dom.pauseMute.classList.toggle('on', !muted);
  }

  toggleView() {
    const mode = this.player.viewMode === 'third' ? 'first' : 'third';
    this.player.setView(mode);
    this.dom.viewMode.textContent = mode === 'third' ? 'THIRD PERSON' : 'FIRST PERSON';
    this.toast('CAMERA', mode === 'third' ? 'Third-person tracking restored.' : 'First-person view. The ape body is now your own.', 'good', 2200);
    this.audio.ui();
  }

  toggleLamp() {
    this.player.lampOn = !this.player.lampOn;
    this.dom.lampText.textContent = this.player.lampOn ? 'HEADLAMP ON' : 'HEADLAMP OFF';
    this.dom.lampIcon.style.color = this.player.lampOn ? 'var(--cyan)' : '#5a6b59';
    this.audio.ui(this.player.lampOn);
  }

  /* ---------------------------------------------------------------- */
  setupTouch() {
    const joy = this.dom.joystick;
    let joyId = null;
    const updateJoy = (e) => {
      const r = joy.getBoundingClientRect();
      const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
      let dx = (e.clientX - cx) / (r.width * .42);
      let dy = (e.clientY - cy) / (r.height * .42);
      const len = Math.hypot(dx, dy);
      if (len > 1) { dx /= len; dy /= len; }
      this.joy.x = dx; this.joy.y = dy;
      this.dom.stick.style.transform = `translate(${dx * 35}px, ${dy * 35}px)`;
    };
    joy.addEventListener('pointerdown', e => {
      e.preventDefault(); joyId = e.pointerId; joy.setPointerCapture(joyId); this.joy.active = true; updateJoy(e);
    });
    joy.addEventListener('pointermove', e => { if (e.pointerId === joyId) { e.preventDefault(); updateJoy(e); } });
    const endJoy = e => {
      if (e.pointerId !== joyId) return;
      joyId = null; this.joy.active = false; this.joy.x = 0; this.joy.y = 0;
      this.dom.stick.style.transform = 'translate(0,0)';
    };
    joy.addEventListener('pointerup', endJoy);
    joy.addEventListener('pointercancel', endJoy);

    const pad = this.dom.lookPad;
    let lookId = null, lx = 0, ly = 0;
    pad.addEventListener('pointerdown', e => {
      e.preventDefault(); lookId = e.pointerId; pad.setPointerCapture(lookId); lx = e.clientX; ly = e.clientY;
    });
    pad.addEventListener('pointermove', e => {
      if (e.pointerId !== lookId || this.state !== 'playing') return;
      e.preventDefault();
      const dx = e.clientX - lx, dy = e.clientY - ly;
      lx = e.clientX; ly = e.clientY;
      this.applyLook(dx, dy, 1.35);
    });
    const endLook = e => { if (e.pointerId === lookId) lookId = null; };
    pad.addEventListener('pointerup', endLook);
    pad.addEventListener('pointercancel', endLook);

    this.dom.touchInteract.addEventListener('click', () => this.tryInteract());
    this.dom.touchJump.addEventListener('click', () => { this.jumpQueued = true; });
    this.dom.touchCrouch.addEventListener('click', () => {
      this.touchCrouch = !this.touchCrouch;
      this.dom.touchCrouch.classList.toggle('on', this.touchCrouch);
    });
    this.dom.touchRun.addEventListener('click', () => {
      this.touchRun = !this.touchRun;
      this.dom.touchRun.classList.toggle('on', this.touchRun);
    });
    this.dom.touchView.addEventListener('click', () => this.toggleView());
    this.dom.touchThrow.addEventListener('click', () => this.throwRock());
    this.dom.touchLamp.addEventListener('click', () => this.toggleLamp());
  }

  /* ---------------------------------------------------------------- */
  input() {
    if (this.state !== 'playing') return { forward: 0, strafe: 0, sprint: false, crouch: false, jump: false };
    const k = this.keys;
    let forward = 0, strafe = 0;
    if (k.get('KeyW') || k.get('ArrowUp')) forward += 1;
    if (k.get('KeyS') || k.get('ArrowDown')) forward -= 1;
    if (k.get('KeyD') || k.get('ArrowRight')) strafe += 1;
    if (k.get('KeyA') || k.get('ArrowLeft')) strafe -= 1;
    forward += -this.joy.y;
    strafe += this.joy.x;
    const len = Math.hypot(forward, strafe);
    if (len > 1) { forward /= len; strafe /= len; }
    return {
      forward, strafe,
      sprint: !!(k.get('ShiftLeft') || k.get('ShiftRight') || this.touchRun),
      crouch: !!(this.crouchToggle || this.touchCrouch),
      jump: this.jumpQueued,
      mag: Math.min(1, len),
    };
  }

  tryInteract() {
    if (this.state === 'note') { this.closeNote(); return; }
    if (this.state !== 'playing') return;
    const it = this.world.getInteractable(this.player.pos);
    if (!it) { this.audio.ui(false); return; }
    this.audio.ui();
    it.onUse(this);
    this.promptRefresh = 0;
  }

  emitNoise(pos, strength = .5, type = 'noise') {
    this.noiseEvents.push({ pos: new THREE.Vector3(pos.x, pos.y || 0, pos.z), strength, type, age: 0, heard: false });
    if (this.noiseEvents.length > 12) this.noiseEvents.shift();
  }

  onFootstep(pos, strength) {
    this.effects.dust(new THREE.Vector3(pos.x, pos.y + .05, pos.z), this.player.sprinting ? 4 : 2);
  }

  onCoreCollected(core) {
    this.coresCollected++;
    this.updateObjective();
    this.toast('ISOTOPE CORE SECURED', `${core.site.code} recovered — ${this.coresCollected}/3. ${this.coresCollected < 3 ? 'The next beacon is live.' : 'Return to the lab terminal.'}`, 'good', 5200);
    if (this.coresCollected >= 3) {
      setTimeout(() => {
        if (this.state !== 'playing') return;
        this.toast('ARRAY COMPLETE', 'All three cores are stable. The ascent terminal is waiting in the lab.', 'warn', 6500);
        this.monster.enraged = true;
        this.monster.hear(this.player.pos, 1, this);
      }, 1200);
    }
  }

  onAscentBegin() {
    this.ascentTimer = 13;
    this.updateObjective();
    this.toast('EMERGENCY ASCENT', 'Shaft pressurising. The lift will arrive in 13 seconds. Hold the lab.', 'warn', 6000);
    this.monster.enraged = true;
    this.monster.hear(this.player.pos, 1.2, this);
    this.shake(.5, .6);
  }

  onLiftReady() {
    this.ascentTimer = 0;
    this.updateObjective();
    this.toast('ASCENT LIFT ONLINE', 'Step onto the centre pad and use the lift.', 'good', 6000);
    this.audio.alarm();
  }

  finishGame() {
    if (this.state === 'win') return;
    this.state = 'win';
    this.dom.mobile.classList.add('hidden');
    this.dom.hud.style.opacity = '0';
    this.dom.hud.style.transition = 'opacity .8s ease';
    if (document.pointerLockElement) document.exitPointerLock?.();
    this.audio.win();
    this.flash = 1;
    this.dom.winStats.innerHTML = `<span>TIME <b>${fmtTime(this.playTime)}</b></span><span>CORES <b>3 / 3</b></span><span>JUNGLE <b>500 × 500 M</b></span>`;
    setTimeout(() => this.dom.win.classList.remove('hidden'), 260);
    this.updateLockHint();
  }

  onDeath() {
    if (this.state !== 'playing') return;
    this.state = 'dead';
    this.dom.mobile.classList.add('hidden');
    this.dom.hud.style.opacity = '0';
    this.dom.hud.style.transition = 'opacity 1s ease';
    if (document.pointerLockElement) document.exitPointerLock?.();
    this.audio.death();
    this.dom.deathStats.innerHTML = `<span>LIFE <b>00:00</b></span><span>CORES <b>${this.coresCollected} / 3</b></span><span>TIME <b>${fmtTime(this.playTime)}</b></span>`;
    setTimeout(() => this.dom.death.classList.remove('hidden'), 500);
    this.updateLockHint();
  }

  onMonsterAlert() {
    this.monsterAlertTimer = 4;
    this.dom.monsterBannerText.textContent = 'IT HEARD YOU. BREAK LINE OF SOUND.';
    this.audio.ui(false);
    if (this.toastCooldown <= 0) {
      this.toast('ACOUSTIC CONTACT', 'Moss.Man is tracking your sound. Stop, crouch, or throw a stone.', 'danger', 4500);
      this.toastCooldown = 9;
    }
  }

  onMonsterRoar(dist) {
    if (dist < 40) this.shake(clamp(.65 - dist / 80, .12, .55), .7);
  }

  heal(amount) {
    this.player.heal(amount);
    this.player.health = Math.min(100, this.player.health);
    this.audio.heal();
    this.effects.burst(new THREE.Vector3(this.player.pos.x, this.player.pos.y + 1.2, this.player.pos.z), 0x8dff7c, 22, 1.3);
  }

  shake(amount, time) {
    this.shakeAmt = Math.max(this.shakeAmt, amount);
    this.shakeTime = Math.max(this.shakeTime, time);
  }

  damageFlash() {
    this.dom.damage.style.opacity = '1';
    setTimeout(() => { this.dom.damage.style.opacity = '0'; }, 180);
  }

  throwRock() {
    if (this.state !== 'playing' || this.throwCd > 0) return;
    this.throwCd = .9;
    const eye = this.player.getEyePosition();
    const dir = this.player.getLookDir();
    const geo = new THREE.DodecahedronGeometry(.11, 0);
    const mat = new THREE.MeshLambertMaterial({ color: 0x5c5b4b, flatShading: true });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(eye).addScaledVector(dir, .6);
    mesh.castShadow = true;
    this.scene.add(mesh);
    const vel = dir.clone().multiplyScalar(19);
    vel.y += 2.2;
    this.rocks.push({ mesh, vel, life: 4, bounced: false });
    this.audio.throwRock();
    this.noiseEvents.push({ pos: eye.clone(), strength: .1, type: 'throw', age: -0.1, heard: false });
    this.toast('STONE THROWN', 'The impact will pull its attention.', 'good', 1600);
  }

  updateRocks(dt) {
    for (let i = this.rocks.length - 1; i >= 0; i--) {
      const r = this.rocks[i];
      r.life -= dt;
      r.vel.y -= 19 * dt;
      r.mesh.position.addScaledVector(r.vel, dt);
      r.mesh.rotation.x += dt * 8; r.mesh.rotation.z += dt * 5;
      const g = this.world.groundAt(r.mesh.position.x, r.mesh.position.z);
      const hitWall = (() => {
        const p = r.mesh.position;
        for (const c of this.world.colliders) {
          if (!c.enabled) continue;
          if (p.x > c.minX && p.x < c.maxX && p.z > c.minZ && p.z < c.maxZ && p.y < 3.4) return true;
        }
        return false;
      })();
      if (r.mesh.position.y <= g + .12 || hitWall || r.life <= 0) {
        const pos = r.mesh.position.clone();
        this.effects.impact(pos, 0x77745d, 9);
        this.audio.impact();
        if (pos.y > g - .5) {
          this.emitNoise(pos, .9, 'rock');
        }
        this.scene.remove(r.mesh);
        r.mesh.geometry.dispose();
        r.mesh.material.dispose();
        this.rocks.splice(i, 1);
      }
    }
  }

  updateObjective() {
    let title, detail;
    if (this.state === 'win') { title = 'SURFACE REACHED'; detail = 'INCIDENT CLOSED'; }
    else if (this.coresCollected < 3) {
      title = 'RECOVER ISOTOPE CORES';
      detail = `${this.coresCollected} / 3 RECOVERED — FOLLOW THE BEACONS`;
    } else if (!this.world.ascentActive) {
      title = 'RETURN TO THE MAIN TERMINAL';
      detail = 'ISOTOPE ARRAY COMPLETE — RETURN TO THE LAB';
    } else if (!this.world.ascentReady) {
      title = 'RIDE THE ASCENT LIFT';
      detail = `EMERGENCY SHAFT PRESSURISING — ${Math.max(0, Math.ceil(this.ascentTimer))} S`;
    } else {
      title = 'ESCAPE THE APE PROJECT';
      detail = 'LIFT LOCKED — STEP ONTO THE CENTRE PAD';
    }
    this.dom.objectiveTitle.textContent = title;
    this.dom.objectiveDetail.textContent = detail;
    this.dom.corePips.forEach((p, i) => p.classList.toggle('filled', i < this.coresCollected));
  }

  /* ---------------------------------------------------------------- */
  toast(title, body, type = 'good', dur = 4000) {
    const el = document.createElement('div');
    el.className = 'toast ' + (type === 'good' ? '' : type);
    const b = document.createElement('b'); b.textContent = title;
    el.appendChild(b);
    el.appendChild(document.createTextNode(body));
    this.dom.toasts.appendChild(el);
    while (this.dom.toasts.children.length > 4) this.dom.toasts.firstChild.remove();
    setTimeout(() => {
      el.style.transition = 'opacity .4s, transform .4s';
      el.style.opacity = '0';
      el.style.transform = 'translateX(10px)';
      setTimeout(() => el.remove(), 450);
    }, dur);
  }

  updateCompass() {
    const heading = ((180 - THREE.MathUtils.radToDeg(this.player.yaw)) % 360 + 360) % 360;
    for (const t of this.compassTicks) {
      const rel = wrapDeg(t.bearing - heading);
      t.el.style.left = (50 + rel / 1.8) + '%';
      t.el.style.opacity = Math.abs(rel) > 100 ? '0' : (t.bearing % 45 === 0 ? '.75' : '.4');
    }
    for (const c of this.compassCards) {
      const rel = wrapDeg(c.bearing - heading);
      c.el.style.left = (50 + rel / 1.8) + '%';
      c.el.style.display = Math.abs(rel) > 100 ? 'none' : 'block';
    }

    let target = null, label = '';
    if (this.coresCollected < 3) {
      const remaining = this.world.cores.filter(c => !c.collected);
      let best = null, bd = Infinity;
      for (const c of remaining) {
        const d = Math.hypot(c.site.x - this.player.pos.x, c.site.z - this.player.pos.z);
        if (d < bd) { bd = d; best = c; }
      }
      if (best) { target = new THREE.Vector3(best.site.x, 0, best.site.z); label = 'NEAREST BEACON'; }
    } else if (!this.world.ascentActive || !this.world.ascentReady) {
      target = new THREE.Vector3(4.75, 0, -5.25);
      label = 'MAIN TERMINAL';
      if (this.world.ascentActive) label = 'ASCENT LIFT';
    } else {
      target = new THREE.Vector3(0, 0, 0);
      label = 'ASCENT LIFT';
    }

    if (target) {
      const dx = target.x - this.player.pos.x, dz = target.z - this.player.pos.z;
      const dist = Math.hypot(dx, dz);
      const bearing = (Math.atan2(dx, -dz) * 180 / Math.PI + 360) % 360;
      const rel = wrapDeg(bearing - heading);
      this.dom.trackerLabel.textContent = label;
      this.dom.trackerDist.textContent = Math.round(dist) + ' M';
      this.dom.trackerBearing.textContent = 'BRG ' + String(Math.round(bearing)).padStart(3, '0') + '°';
      this.objMark.style.display = Math.abs(rel) > 100 ? 'none' : 'block';
      this.objMark.style.left = (50 + rel / 1.8) + '%';
      this.objMark.style.background = label.includes('LIFT') ? 'var(--cyan)' : 'var(--amber)';
      this.objMark.style.boxShadow = `0 0 10px ${label.includes('LIFT') ? 'var(--cyan)' : 'var(--amber)'}`;
    } else {
      this.dom.trackerLabel.textContent = 'NO SIGNAL';
      this.dom.trackerDist.textContent = '—';
      this.dom.trackerBearing.textContent = '—';
      this.objMark.style.display = 'none';
    }

    const distHome = Math.hypot(this.player.pos.x, this.player.pos.z);
    if (distHome > 12 && this.coresCollected < 3) {
      const bearing = (Math.atan2(-this.player.pos.x, this.player.pos.z) * 180 / Math.PI + 360) % 360;
      const rel = wrapDeg(bearing - heading);
      this.homeMark.style.display = Math.abs(rel) > 100 ? 'none' : 'block';
      this.homeMark.style.left = (50 + rel / 1.8) + '%';
    } else this.homeMark.style.display = 'none';
  }

  updateHud(force = false) {
    const p = this.player, m = this.monster;
    const hp = clamp(p.health, 0, 100);
    this.dom.healthFill.style.width = hp + '%';
    this.dom.healthFill.classList.toggle('warn', hp <= 55 && hp > 28);
    this.dom.healthFill.classList.toggle('crit', hp <= 28);
    this.dom.healthNum.textContent = String(Math.ceil(hp));
    this.dom.staminaFill.style.width = p.stamina + '%';
    this.dom.staminaFill.classList.toggle('low', p.stamina < 25);
    this.dom.staminaNum.textContent = String(Math.ceil(p.stamina));
    this.dom.lampText.textContent = p.lampOn ? 'HEADLAMP ON' : 'HEADLAMP OFF';
    this.dom.lampIcon.style.color = p.lampOn ? 'var(--cyan)' : '#5a6b59';
    const noiseLit = Math.round(p.noise * 8);
    this.dom.noisePips.forEach((el, i) => el.classList.toggle('on', i < noiseLit));
    this.dom.noisePips.forEach((el, i) => el.style.opacity = i < noiseLit ? '1' : '.35');

    const threat = m.threat;
    this.dom.threatBars.forEach((el, i) => {
      const on = i < Math.round(threat * 8);
      el.classList.toggle('on', on);
      el.style.height = on ? (5 + i * 1.15) + 'px' : '3px';
    });
    const hot = threat > .48;
    this.dom.threatCard.classList.toggle('hot', hot);
    this.dom.crosshair.classList.toggle('hot', hot);
    let word = 'SILENT';
    if (threat > .82) word = 'IMMINENT';
    else if (threat > .58) word = 'HUNTING';
    else if (threat > .34) word = 'NEAR';
    else if (threat > .12) word = 'LISTENING';
    else if (threat > .02) word = 'DISTANT';
    this.dom.threatWord.textContent = word;

    const banner = m.state === 'hunt' && m.distanceToPlayer < 48 && this.state === 'playing';
    this.dom.monsterBanner.classList.toggle('show', banner || this.monsterAlertTimer > 0);
    if (banner) {
      this.dom.monsterBannerText.textContent = m.distanceToPlayer < 16 ? 'IT IS ON YOU. RUN. DO NOT RUN STRAIGHT.' : 'IT IS TRACKING YOUR SOUND. GO QUIET.';
    }
    this.updateCompass();
  }

  updatePrompt() {
    if (this.state !== 'playing') {
      this.dom.prompt.classList.remove('show');
      return;
    }
    const it = this.world.getInteractable(this.player.pos);
    if (it) {
      const label = typeof it.label === 'function' ? it.label() : it.label;
      this.dom.promptLabel.textContent = label;
      this.dom.prompt.classList.add('show');
      this.dom.reticleHint.classList.remove('show');
    } else {
      this.dom.prompt.classList.remove('show');
      const nearLift = Math.hypot(this.player.pos.x, this.player.pos.z) < 3 && this.world.ascentActive && !this.world.ascentReady;
      this.dom.reticleHint.textContent = nearLift ? 'LIFT ARRIVING...' : '';
      this.dom.reticleHint.classList.toggle('show', nearLift);
    }
  }

  updateCamera(dt) {
    const p = this.player;
    const cam = this.camera;
    if (this.state === 'title') {
      const t = this.time * .075;
      const r = 5.6;
      cam.position.set(Math.sin(t) * r, 2.85 + Math.sin(t * .6) * .18, Math.cos(t) * r + 1.1);
      cam.lookAt(0, 1.55, -1.2);
      cam.fov = 67;
      cam.updateProjectionMatrix();
      return;
    }

    let targetFov = 70 + (p.sprinting ? 4.2 : 0) + (p.crouchBlend * -2);
    cam.fov = damp(cam.fov, targetFov, 6, dt);
    cam.updateProjectionMatrix();

    const dir = p.getLookDir();
    if (p.viewMode === 'first') {
      const eye = p.getEyePosition();
      const sway = Math.sin(p.walkPhase * 2) * .035 * (p.analog * .8 + .2);
      const strafe = Math.sin(p.walkPhase) * .018 * p.analog;
      eye.y += sway;
      eye.x += Math.cos(p.yaw) * strafe;
      eye.z -= Math.sin(p.yaw) * strafe;
      cam.position.copy(eye);
      this.applyCameraShake();
      cam.lookAt(cam.position.clone().add(dir));
      cam.rotation.z += Math.sin(p.walkPhase) * .004 * p.analog;
    } else {
      const target = p.getTarget();
      const crouchOffset = p.crouchBlend * .2;
      const dist = (5.15 - p.crouchBlend * .55) * (this.mobileLayout ? 1.06 : 1);
      const desired = target.clone().addScaledVector(dir, -dist);
      desired.y += crouchOffset;
      this.scene.updateMatrixWorld();
      const toCam = desired.clone().sub(target);
      const len = toCam.length();
      toCam.normalize();
      this.raycaster.set(target, toCam);
      this.raycaster.far = len;
      const hits = this.raycaster.intersectObjects(this.world.cameraBlockers, false);
      let actualDist = len;
      if (hits.length) actualDist = Math.max(1.1, hits[0].distance - .28);
      const camPos = target.clone().addScaledVector(toCam, actualDist);
      const floor = this.world.groundAt(camPos.x, camPos.z) + .38;
      if (camPos.y < floor) camPos.y = floor;
      if (this.world.insideLab(camPos.x, camPos.z)) camPos.y = Math.min(camPos.y, 4.95);
      cam.position.copy(camPos);
      this.applyCameraShake();
      cam.lookAt(target.clone().addScaledVector(dir, 4));
    }

    this.shakeAmt = Math.max(0, this.shakeAmt - dt * 2.3);
    this.shakeTime = Math.max(0, this.shakeTime - dt);
  }

  applyCameraShake() {
    if (this.shakeTime <= 0) return;
    const a = this.shakeAmt * (this.shakeTime > 0 ? 1 : 0);
    this.camera.position.x += (Math.random() - .5) * a * .35;
    this.camera.position.y += (Math.random() - .5) * a * .35;
    this.camera.position.z += (Math.random() - .5) * a * .35;
    this.camera.rotation.z += (Math.random() - .5) * a * .03;
  }

  /* ---------------------------------------------------------------- */
  update(dt) {
    this.time += dt;
    this.toastCooldown = Math.max(0, this.toastCooldown - dt);
    this.throwCd = Math.max(0, this.throwCd - dt);
    this.monsterAlertTimer = Math.max(0, this.monsterAlertTimer - dt);
    const playing = this.state === 'playing';
    const simActive = playing;
    const inside = this.world.insideLab(this.player.pos.x, this.player.pos.z) && this.player.pos.y < 4.8;

    if (playing) this.playTime += dt;

    if (simActive) {
      const input = this.input();
      this.player.update(dt, input, this);
      this.jumpQueued = false;
      this.world.update(dt, this.time, this.player, this);
      this.monster.update(dt, this.time, this.player, this);
      this.updateRocks(dt);
      this.effects.update(dt, this.time, this.player, inside);

      for (const ev of this.noiseEvents) ev.age += dt;
      this.noiseEvents = this.noiseEvents.filter(ev => ev.age < 4.2);

      // monster proximity can make the camera flinch
      if (this.monster.distanceToPlayer < 18 && this.monster.state === 'hunt') this.shake(Math.max(this.shakeAmt, .08), .1);

      // ascent countdown UI
      if (this.world.ascentActive && !this.world.ascentReady) {
        this.ascentTimer = Math.max(0, 13 - (this.time - this.world.ascentStart));
        this.updateObjective();
      }

      // intro roar
      this.introRoar -= dt;
      if (this.introRoar <= 0) {
        this.introRoar = 999;
        this.audio.monsterRoar(0, .45);
        this.toast('DISTANT VOCALISATION', 'Something huge just exhaled in the tree line.', 'warn', 6000);
      }

      // weather
      this.lightningTimer -= dt;
      if (!inside && this.lightningTimer <= 0) {
        this.lightningTimer = 14 + Math.random() * 20;
        this.flash = 1;
        this.thunderTimer = .4 + Math.random() * 1.4;
      }
      if (this.thunderTimer > 0) {
        this.thunderTimer -= dt;
        if (this.thunderTimer <= 0) {
          this.audio._noise({ dur: 2.4, gain: .09, type: 'lowpass', freq: 440, endFreq: 60, send: .5 });
          this.audio._tone({ freq: 62, endFreq: 30, dur: 2.2, type: 'sine', gain: .045, send: .5 });
        }
      }

      this.updatePrompt();
      this.updateHud();

      this.audio.update(dt, {
        threat: this.monster.threat,
        indoors: inside,
        raining: !inside,
        paused: false,
      });
    } else if (this.state === 'title') {
      this.world.update(dt, this.time, this.player, null);
      this.player.updateModel(dt, 0);
      this.effects.update(dt, this.time, this.player, true);
      this.monster.updateModel(dt, 0);
      this.monster.model.position.copy(this.monster.pos);
      this.monster.model.rotation.y = this.monster.yaw;
    } else if (this.state === 'dead' || this.state === 'win') {
      this.effects.update(dt, this.time, this.player, inside);
    }

    this.flash = Math.max(0, this.flash - dt * 2.6);
    this.dom.white.style.opacity = String(this.flash * .55);
    this.updateCamera(dt);
  }

  render() {
    this.renderer.render(this.scene, this.camera);
  }

  animate() {
    requestAnimationFrame(() => this.animate());
    const dt = Math.min(this.clock.getDelta(), .05);
    this.update(dt);
    this.render();
  }
}

new Game();

