  inner.position.y = .15; g.add(inner);
  const ring = new THREE.Mesh(new THREE.TorusGeometry(1.48, .05, 4, 24), new THREE.MeshBasicMaterial({ color: 0x6ff8d2, transparent: true, opacity: .32, toneMapped: false }));
