import * as THREE from 'three';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const damp = (a, b, lambda, dt) => a + (b - a) * (1 - Math.exp(-lambda * dt));

function limbBox(w, h, d, mat, x, y, z) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  return m;
}

export class Player {
  constructor(scene, world) {
    this.world = world;
    this.scene = scene;
    this.pos = new THREE.Vector3(world.spawn.x, world.groundAt(world.spawn.x, world.spawn.z), world.spawn.z);
    this.yaw = world.spawn.yaw;
    this.pitch = -0.03;
    this.radius = 0.48;
    this.height = 2.05;
    this.vel = new THREE.Vector3();
    this.vy = 0;
    this.grounded = true;
    this.health = 100;
    this.stamina = 100;
    this.maxHealth = 100;
    this.maxStamina = 100;
    this.crouchBlend = 0;
    this.quadBlend = 0;
    this.walkPhase = 0;
    this.stepTimer = 0;
    this.noise = 0;
    this.speedNow = 0;
    this.analog = 0;
    this.moving = false;
    this.sprinting = false;
    this.crouching = false;
    this.viewMode = 'third';
    this.lampOn = true;
    this.invuln = 0;
    this.hurtTimer = 0;
    this.exhausted = false;
    this.modelYaw = this.yaw;
    this.bob = 0;
    this.landTimer = 0;
    this.distanceWalked = 0;
    this.dead = false;
    this.buildModel();
    this.buildLamp();
  }

  buildModel() {
    const fur = new THREE.MeshLambertMaterial({ color: 0x2d2b22, flatShading: true });
    const fur2 = new THREE.MeshLambertMaterial({ color: 0x3d392b, flatShading: true });
    const furDark = new THREE.MeshLambertMaterial({ color: 0x1d1c16, flatShading: true });
    const skin = new THREE.MeshLambertMaterial({ color: 0x67553e, flatShading: true });
    const skinDark = new THREE.MeshLambertMaterial({ color: 0x3d3327, flatShading: true });
    this.furMats = { fur, fur2, furDark, skin };
    const model = new THREE.Group();
    this.model = model;
    this.scene.add(model);

    const bodyPivot = new THREE.Group();
    bodyPivot.position.y = 1.08;
    model.add(bodyPivot);
    this.bodyPivot = bodyPivot;

    const torso = limbBox(0.92, 0.95, 0.58, fur, 0, 0.18, 0);
    bodyPivot.add(torso);
    const chest = limbBox(0.7, 0.55, 0.1, skin, 0, 0.26, 0.3);
    bodyPivot.add(chest);
    // pixel fur clumps
    for (let i = 0; i < 12; i++) {
      const s = 0.12 + Math.random() * 0.16;
      const p = limbBox(s, s * 1.6, s, i % 3 ? fur2 : furDark, (Math.random() - .5) * .85, (Math.random() - .5) * .8, (Math.random() - .5) * .55);
      torso.add(p);
    }
    const back = limbBox(0.6, 0.3, 0.38, skinDark, 0, 0.55, -0.12);
    bodyPivot.add(back);

    const headPivot = new THREE.Group();
    headPivot.position.set(0, 0.82, 0.14);
    bodyPivot.add(headPivot);
    this.headPivot = headPivot;
    this.head = limbBox(0.62, 0.54, 0.58, fur2, 0, 0.1, 0);
    headPivot.add(this.head);
    const face = limbBox(0.5, 0.32, 0.18, skinDark, 0, 0.02, 0.32);
    headPivot.add(face);
    const muzzle = limbBox(0.38, 0.2, 0.24, skin, 0, -0.06, 0.38);
    headPivot.add(muzzle);
    const nose = limbBox(0.13, 0.08, 0.05, furDark, 0, 0.01, 0.51);
    headPivot.add(nose);
    for (const s of [-1, 1]) {
      const eye = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.07, 0.035), new THREE.MeshBasicMaterial({ color: 0xc1ff84, toneMapped: false }));
      eye.position.set(s * 0.16, 0.18, 0.305);
      headPivot.add(eye);
      const brow = limbBox(0.16, 0.06, 0.08, furDark, s * 0.16, 0.25, 0.3);
      headPivot.add(brow);
      const ear = limbBox(0.14, 0.16, 0.08, fur, s * 0.33, 0.2, 0.02);
      headPivot.add(ear);
    }

    const makeArm = (side) => {
      const shoulder = new THREE.Group();
      shoulder.position.set(side * 0.53, 0.58, 0);
      bodyPivot.add(shoulder);
      const upper = limbBox(0.26, 0.7, 0.3, fur, 0, -0.3, 0);
      shoulder.add(upper);
      const elbow = new THREE.Group();
      elbow.position.y = -0.64;
      shoulder.add(elbow);
      const fore = limbBox(0.22, 0.62, 0.25, fur2, 0, -0.29, 0);
      elbow.add(fore);
      const hand = limbBox(0.24, 0.22, 0.28, skinDark, 0, -0.63, 0.03);
      elbow.add(hand);
      for (let i = 0; i < 3; i++) {
        const knuckle = limbBox(0.05, 0.14, 0.2, skin, -0.07 + i * 0.07, -0.72, 0.07);
        elbow.add(knuckle);
      }
      return { shoulder, elbow };
    };
    this.armL = makeArm(-1);
    this.armR = makeArm(1);

    const makeLeg = (side) => {
      const hip = new THREE.Group();
      hip.position.set(side * 0.26, 1.02, 0);
      model.add(hip);
      const thigh = limbBox(0.3, 0.58, 0.34, fur2, 0, -0.25, 0);
      hip.add(thigh);
      const knee = new THREE.Group();
      knee.position.y = -0.54;
      hip.add(knee);
      const shin = limbBox(0.24, 0.5, 0.27, fur, 0, -0.24, 0);
      knee.add(shin);
      const foot = limbBox(0.3, 0.16, 0.46, furDark, 0, -0.5, 0.12);
      knee.add(foot);
      return { hip, knee };
    };
    this.legL = makeLeg(-1);
    this.legR = makeLeg(1);

    // back ridge / spine plates
    for (let i = 0; i < 4; i++) {
      const plate = limbBox(0.18, 0.16, 0.12, skinDark, 0, 0.55 - i * 0.16, -0.3 + i * 0.05);
      bodyPivot.add(plate);
    }

    model.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    model.position.copy(this.pos);
    model.rotation.y = this.yaw;
  }

  buildLamp() {
    const spot = new THREE.SpotLight(0xfff0c8, 105, 34, Math.PI / 7.2, 0.55, 1.35);
    spot.castShadow = false;
    spot.position.set(0, 1.7, 0);
    spot.target.position.set(0, 0, 6);
    this.scene.add(spot);
    this.scene.add(spot);
    this.scene.add(spot.target);
    const warm = new THREE.PointLight(0xffd9a0, 4.5, 7, 2);
    warm.position.set(0, 1.5, 0);
    this.scene.add(warm);
    this.lamp = spot;
    this.lampGlow = warm;
  }

  setView(mode) {
    this.viewMode = mode;
  }

  update(dt, input, game) {
    if (this.dead) return;
    const world = this.world;
    this.invuln = Math.max(0, this.invuln - dt);
    this.hurtTimer = Math.max(0, this.hurtTimer - dt);
    this.landTimer = Math.max(0, this.landTimer - dt);

    const forwardInput = input.forward || 0;
    const strafeInput = input.strafe || 0;
    const mag = Math.min(1, Math.hypot(forwardInput, strafeInput));
    this.analog = mag;
    this.crouching = !!input.crouch;
    const wantSprint = !!input.sprint && !this.crouching && mag > 0.15;

    if (this.stamina <= 0.5) this.exhausted = true;
    if (this.exhausted && this.stamina > 32) this.exhausted = false;
    this.sprinting = wantSprint && !this.exhausted && this.stamina > 0.5;
    this.crouchBlend = damp(this.crouchBlend, this.crouching ? 1 : 0, 12, dt);

    let targetSpeed;
    if (this.crouching) targetSpeed = 1.75;
    else if (this.sprinting) targetSpeed = 6.85;
    else targetSpeed = 3.45;
    targetSpeed *= mag;

    const f = new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw));
    const r = new THREE.Vector3(-Math.cos(this.yaw), 0, Math.sin(this.yaw));
    const wish = new THREE.Vector3().addScaledVector(f, forwardInput).addScaledVector(r, strafeInput);
    if (wish.lengthSq() > 1) wish.normalize();
    this.moving = wish.lengthSq() > 0.001;

    const targetVel = wish.multiplyScalar(targetSpeed);
    const accel = this.grounded ? 16 : 4;
    this.vel.x = damp(this.vel.x, targetVel.x, accel, dt);
    this.vel.z = damp(this.vel.z, targetVel.z, accel, dt);
    if (!this.moving && this.grounded) {
      this.vel.x = damp(this.vel.x, 0, 20, dt);
      this.vel.z = damp(this.vel.z, 0, 20, dt);
    }

    // knockback
    if (this.hurtTimer > 0) {
      this.vel.x *= 0.965;
      this.vel.z *= 0.965;
    }

    const beforeX = this.pos.x, beforeZ = this.pos.z;
    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    world.resolveCollisions(this.pos, this.radius);

    // outside the lab, prevent walking through the sealed shell corners
    const ground = world.groundAt(this.pos.x, this.pos.z);

    if (input.jump && this.grounded && !this.crouching) {
      this.vy = 4.8;
      this.grounded = false;
      if (game) game.audio.step('sprint');
    }
    if (!this.grounded) {
      this.vy -= 14.5 * dt;
      this.pos.y += this.vy * dt;
      if (this.pos.y <= ground) {
        this.pos.y = ground;
        if (this.vy < -4) this.landTimer = 0.2;
        this.vy = 0;
        this.grounded = true;
      }
    } else {
      this.pos.y = damp(this.pos.y, ground, 18, dt);
      if (Math.abs(this.pos.y - ground) > 0.55) { this.grounded = false; this.vy = 0; }
    }

    const dx = this.pos.x - beforeX, dz = this.pos.z - beforeZ;
    const dist = Math.hypot(dx, dz);
    this.speedNow = dt > 0 ? dist / dt : 0;
    this.distanceWalked += dist;
    const actualSpeedRatio = clamp(this.speedNow / 6.85, 0, 1);

    // stamina
    if (this.sprinting && this.moving && this.grounded) this.stamina = Math.max(0, this.stamina - 23 * dt);
    else this.stamina = Math.min(this.maxStamina, this.stamina + (this.crouching ? 20 : 14) * dt);

    // noise signature
    let noiseTarget = 0.02;
    if (this.moving && this.grounded) {
      if (this.crouching) noiseTarget = 0.13 + actualSpeedRatio * .07;
      else if (this.sprinting) noiseTarget = 0.92 + actualSpeedRatio * .08;
      else noiseTarget = 0.45 + actualSpeedRatio * .1;
    } else if (!this.grounded) noiseTarget = 0.25;
    this.noise = damp(this.noise, noiseTarget, 7, dt);

    // footsteps
    if (this.grounded && this.moving) {
      const stride = this.sprinting ? 1.55 : (this.crouching ? 1.05 : 1.5);
      this.stepTimer -= dist;
      if (this.stepTimer <= 0) {
        this.stepTimer = stride;
        if (game) {
          game.audio.step(this.crouching ? 'crouch' : (this.sprinting ? 'sprint' : 'walk'));
          if (!this.crouching) game.onFootstep?.(this.pos, this.sprinting ? .55 : .28);
        }
        this.bob = this.sprinting ? .3 : .18;
      }
    } else {
      this.stepTimer = Math.min(this.stepTimer, 0.15);
    }
    this.bob = damp(this.bob, 0, 9, dt);

    // model facing
    const modelTargetYaw = this.moving ? Math.atan2(this.vel.x, this.vel.z) : this.modelYaw;
    let dyaw = ((modelTargetYaw - this.modelYaw + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
    this.modelYaw += dyaw * Math.min(1, dt * 10);
    this.updateModel(dt, actualSpeedRatio);

    // lamp
    this.lamp.visible = this.lampOn;
    this.lampGlow.visible = this.lampOn;
    const eye = this.getEyePosition();
    const look = this.getLookDir();
    this.lamp.position.copy(eye).addScaledVector(look, 0.2);
    this.lamp.target.position.copy(eye).addScaledVector(look, 14);
    this.lamp.target.position.y -= 1.2;
    this.lampGlow.position.copy(eye);
    this.lampGlow.position.y -= 0.4;

    this.health = Math.min(this.maxHealth, this.health + (this.hurtTimer <= 0 && this.health < 35 ? 1.5 * dt : 0));
  }

  updateModel(dt, speedRatio) {
    const crouch = this.crouchBlend;
    const quadTarget = (this.sprinting && this.moving) ? 1 : 0;
    this.quadBlend = damp(this.quadBlend, quadTarget, 6, dt);
    const quad = this.quadBlend;
    const run = clamp(this.speedNow / 6.85, 0, 1);
    const phaseSpeed = this.sprinting ? 13.5 : (this.crouching ? 5.2 : 8.1);
    if (this.moving) this.walkPhase += dt * phaseSpeed * Math.max(.25, run + this.crouching * .3);
    else this.walkPhase += dt * 1.2;

    const swing = Math.sin(this.walkPhase) * (this.moving ? (0.38 + run * 0.62) : 0.03);
    const swing2 = Math.cos(this.walkPhase) * (this.moving ? (0.3 + run * 0.5) : 0.02);

    this.model.position.copy(this.pos);
    this.model.rotation.y = this.modelYaw;

    // torso posture
    this.bodyPivot.position.y = 1.08 - crouch * 0.38 - quad * 0.43 + Math.abs(swing) * 0.03 + (this.grounded ? 0 : 0.05);
    this.bodyPivot.rotation.x = crouch * 0.32 + quad * 0.92 + (this.grounded ? 0 : -0.08);
    this.bodyPivot.rotation.z = swing2 * 0.045;
    this.headPivot.rotation.x = -crouch * 0.2 - quad * 0.55 + Math.sin(this.walkPhase * 2) * 0.015;
    this.headPivot.rotation.y = this.moving ? 0 : Math.sin(this.walkPhase * .35) * .15;

    // arms: quadruped reaches forward/down, upright swings opposite legs
    const armBase = quad * 1.16 - crouch * 0.1;
    this.armL.shoulder.rotation.x = -swing * (1 - quad * .45) + armBase;
    this.armR.shoulder.rotation.x = swing * (1 - quad * .45) + armBase;
    this.armL.shoulder.rotation.z = -0.08 - quad * 0.15;
    this.armR.shoulder.rotation.z = 0.08 + quad * 0.15;

import * as THREE from 'three';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const damp = (a, b, lambda, dt) => a + (b - a) * (1 - Math.exp(-lambda * dt));
const wrapAngle = a => ((a + Math.PI * 3) % (Math.PI * 2)) - Math.PI;

function box(w, h, d, mat, x, y, z) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.castShadow = true; m.receiveShadow = true;
  return m;
}

export class Monster {
  constructor(scene, world, spawn = { x: 112, z: 88 }) {
    this.scene = scene;
    this.world = world;
    this.pos = new THREE.Vector3(spawn.x, world.groundAt(spawn.x, spawn.z), spawn.z);
    this.yaw = -2.2;
    this.radius = 0.95;
    this.speed = 0;
    this.maxSpeed = 33 / 3.6; // 9.17 m/s
    this.state = 'wander';
    this.stateTime = 0;
    this.lastHeard = new THREE.Vector3().copy(this.pos);
    this.lastHeardAge = 99;
    this.searchTimer = 0;
    this.attackCd = 0;
    this.roarCd = 6;
    this.stepTravel = 0;
    this.stuck = 0;
    this.wanderTimer = 0;
    this.wanderTarget = this.pickWanderTarget();
    this.attackAnim = 0;
    this.attackAnimTime = 0;
    this.huntingAnnounced = false;
    this.distanceToPlayer = 999;
    this.threat = 0;
    this.pan = 0;
    this.enraged = false;
    this.phase = Math.random() * 10;
    this.trailTimer = 0;
    this.breathTimer = 0;
    this.buildModel();
  }

  buildModel() {
    const base = new THREE.MeshLambertMaterial({ color: 0x3f5c2b, flatShading: true, emissive: 0x071006 });
    const base2 = new THREE.MeshLambertMaterial({ color: 0x4d6d31, flatShading: true, emissive: 0x060d05 });
    const dark = new THREE.MeshLambertMaterial({ color: 0x1a331b, flatShading: true });
    const stripe = new THREE.MeshLambertMaterial({ color: 0x173a1b, flatShading: true, emissive: 0x020803 });
    const belly = new THREE.MeshLambertMaterial({ color: 0x6d8342, flatShading: true });
    const skin = new THREE.MeshLambertMaterial({ color: 0x4b5931, flatShading: true });
    const mouthMat = new THREE.MeshBasicMaterial({ color: 0x190504 });
    const toothMat = new THREE.MeshLambertMaterial({ color: 0xc6bd95, flatShading: true });
    const eyeSocket = new THREE.MeshBasicMaterial({ color: 0x081107 });
    this.mats = { base, base2, dark, stripe, belly, skin };

    const model = new THREE.Group();
    this.model = model;
    this.scene.add(model);

    const body = new THREE.Group();
    body.position.y = 1.52;
    model.add(body);
    this.body = body;
    const torso = box(1.32, 1.22, 0.86, base, 0, 0.16, 0);
    body.add(torso);
    // massive shoulders
    const shoulders = box(1.62, 0.44, 0.92, base2, 0, 0.62, 0);
    body.add(shoulders);
    const chest = box(0.84, 0.6, 0.12, belly, 0, 0.12, 0.44);
    body.add(chest);
    // moss stripes wrapping torso
    for (let i = 0; i < 7; i++) {
      const s = box(0.95 + Math.random() * 0.35, 0.1 + Math.random() * 0.12, 0.9, stripe, (Math.random() - .5) * .2, .6 - i * .2, 0);
      s.scale.x = 1.02 + Math.random() * 0.05;
      body.add(s);
    }
    // moss clumps
    for (let i = 0; i < 16; i++) {
      const c = box(0.08 + Math.random() * .16, 0.06 + Math.random() * .12, 0.08 + Math.random() * .14, base2,
        (Math.random() - .5) * 1.2, (Math.random() - .5) * 1.1, .44 + Math.random() * .05);
      body.add(c);
    }
    // spine ridge
    for (let i = 0; i < 5; i++) {
      const sp = box(0.14, 0.24 + i * .03, 0.18, dark, 0, 0.72 - i * .24, -0.46);
      body.add(sp);
    }

    const head = new THREE.Group();
    head.position.set(0, 0.92, 0.12);
    body.add(head);
    this.head = head;
    const skull = box(0.78, 0.6, 0.68, base, 0, 0.1, 0);
    head.add(skull);
    const crown = box(0.84, 0.2, 0.7, base2, 0, 0.4, -0.02);
    head.add(crown);
    // eyeless pits
    for (const s of [-1, 1]) {
      const pit = box(0.18, 0.12, 0.035, eyeSocket, s * 0.2, 0.22, 0.345);
      head.add(pit);
      const ridge = box(0.26, 0.07, 0.07, stripe, s * 0.2, 0.32, 0.34);
      head.add(ridge);
      const cheek = box(0.2, 0.3, 0.1, skin, s * 0.32, -0.05, 0.34);
      head.add(cheek);
    }
    const muzzle = box(0.52, 0.25, 0.2, skin, 0, -0.16, 0.37);
    head.add(muzzle);
    const mouthPivot = new THREE.Group();
    mouthPivot.position.set(0, -0.19, 0.46);
    head.add(mouthPivot);
    this.mouthPivot = mouthPivot;
    const mouth = box(0.58, 0.15, 0.09, mouthMat, 0, -0.04, 0);
    mouthPivot.add(mouth);
    this.mouth = mouth;
    for (let i = 0; i < 8; i++) {
      const tooth = box(0.05, 0.07, 0.04, toothMat, -0.24 + i * 0.068, 0.015, 0.055);
      mouthPivot.add(tooth);
    }
    for (let i = 0; i < 7; i++) {
      const tooth = box(0.045, 0.06, 0.035, toothMat, -0.2 + i * 0.067, -0.105, 0.06);
      mouthPivot.add(tooth);
    }
    // jaw lower
    const jaw = box(0.54, 0.14, 0.16, skin, 0, -0.15, 0.04);
    mouthPivot.add(jaw);
    this.jaw = jaw;

    const makeArm = side => {
      const shoulder = new THREE.Group();
      shoulder.position.set(side * 0.88, 0.55, 0);
      body.add(shoulder);
      const upper = box(0.38, 0.9, 0.42, base, 0, -0.42, 0);
      shoulder.add(upper);
      const elbow = new THREE.Group();
      elbow.position.y = -0.86;
      shoulder.add(elbow);
      const fore = box(0.32, 0.85, 0.36, base2, 0, -0.4, 0);
      elbow.add(fore);
      const hand = box(0.38, 0.4, 0.45, skin, 0, -0.92, 0.03);
      elbow.add(hand);
      for (let i = 0; i < 4; i++) {
        const finger = box(0.07, 0.3, 0.1, skin, -0.13 + i * 0.09, -1.16, 0.1);
        elbow.add(finger);
      }
      // moss stripes on arm
      for (let i = 0; i < 4; i++) {
        const st = box(0.4, 0.07, 0.44, stripe, 0, -0.2 - i * 0.22, 0);
        shoulder.add(st);
      }
      for (let i = 0; i < 5; i++) {
        const m = box(0.1, 0.09, 0.08, base2, (Math.random() - .5) * .25, -Math.random() * .85, .18 + Math.random() * .06);
        shoulder.add(m);
      }
      return { shoulder, elbow };
    };
    this.armL = makeArm(-1);
    this.armR = makeArm(1);
    this.armR = makeArm(1);

    const makeLeg = side => {
      const hip = new THREE.Group();
      hip.position.set(side * 0.38, 1.26, 0);
      model.add(hip);
      const thigh = box(0.46, 0.82, 0.5, base, 0, -0.35, 0);
      hip.add(thigh);
      const knee = new THREE.Group();
      knee.position.y = -0.76;
      hip.add(knee);
      const shin = box(0.36, 0.7, 0.38, base2, 0, -0.32, 0);
      knee.add(shin);
      const foot = box(0.44, 0.22, 0.68, skin, 0, -0.68, 0.14);
      knee.add(foot);
      for (let i = 0; i < 3; i++) {
        const toe = box(0.1, 0.09, 0.16, skin, -0.13 + i * 0.13, -0.72, 0.5);
        knee.add(toe);
      }
      return { hip, knee };
    };
    this.legL = makeLeg(-1);
    this.legR = makeLeg(1);

    // hanging moss vines
    this.vines = [];
    for (let i = 0; i < 8; i++) {
      const v = box(0.035, 0.4 + Math.random() * .6, 0.035, base2, (Math.random() - .5) * 1.4, 0.2 + Math.random() * .4, -0.45);
      body.add(v); this.vines.push(v);
    }

    // faint green bio-glow to read in the dark
    const glow = new THREE.PointLight(0x62b24a, 2.2, 5, 2);
    glow.position.set(0, 1.8, 0.2);
    model.add(glow);
    this.glow = glow;

    // flies around the head
    const flyCount = 10;
    const geo = new THREE.BufferGeometry();
    const arr = new Float32Array(flyCount * 3);
    geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    this.flyGeo = geo;
    this.flyBase = [];
    for (let i = 0; i < flyCount; i++) this.flyBase.push({ a: Math.random() * 6.28, r: .5 + Math.random() * 1.1, y: 1.7 + Math.random() * 1.4, s: .4 + Math.random() * 1.2 });
    this.flies = new THREE.Points(geo, new THREE.PointsMaterial({ color: 0xc6e58a, size: .09, transparent: true, opacity: .7, depthWrite: false, blending: THREE.AdditiveBlending }));
    this.scene.add(this.flies);

    model.position.copy(this.pos);
    model.rotation.y = this.yaw;
  }

  pickWanderTarget(anchor = this.pos) {
    const a = Math.random() * Math.PI * 2;
    const r = 18 + Math.random() * 70;
    const x = clamp(anchor.x + Math.cos(a) * r, -235, 235);
    const z = clamp(anchor.z + Math.sin(a) * r, -235, 235);
    return new THREE.Vector3(x, 0, z);
  }

  hear(pos, strength, game, predelay = 0) {
    const spread = 3 + (1 - strength) * 11;
    this.lastHeard.set(
      pos.x + (Math.random() - .5) * spread,
      0,
      pos.z + (Math.random() - .5) * spread
    );
    this.lastHeardAge = 0;
    if (this.state !== 'hunt') {
      this.state = 'hunt';
      this.stateTime = 0;
      if (game) {
        const dist = this.pos.distanceTo(pos);
        if (dist < 95) this.roar(game, dist);
        if (dist < 110) game.onMonsterAlert?.();
      }
    }
  }

  roar(game, dist = 30) {
    if (!game || this.roarCd > 0) return;
    this.roarCd = 7 + Math.random() * 5;
    const pan = this.pan;
    const vol = clamp(1.25 - dist / 150, .18, 1);
    game.audio.monsterRoar(pan, vol);
    game.onMonsterRoar?.(dist);
  }

  update(dt, time, player, game) {
    if (player.dead) { this.updateModel(dt, 0); return; }
    const toPlayer = new THREE.Vector3(player.pos.x - this.pos.x, 0, player.pos.z - this.pos.z);
    const dist = toPlayer.length();
    this.distanceToPlayer = dist;
    const dirToPlayer = Math.atan2(toPlayer.x, toPlayer.z);
    this.pan = Math.sin(wrapAngle(dirToPlayer - player.yaw));

    this.attackCd = Math.max(0, this.attackCd - dt);
    this.roarCd = Math.max(0, this.roarCd - dt);
    this.lastHeardAge += dt;
    this.stateTime += dt;
    this.attackAnim = Math.max(0, this.attackAnim - dt);

    // acoustic detection from continuous player noise
    const noiseRange = (this.enraged ? 10 : 8) + (this.enraged ? 76 : 62) * player.noise;
    if (player.noise > 0.06 && dist < noiseRange) {
      this.hear(player.pos, player.noise, game);
    }
    // discrete noise events (doors, rocks, cores)
    if (game?.noiseEvents) {
      for (const ev of game.noiseEvents) {
        if (ev.heard || ev.age > 2.4) continue;
        const d = Math.hypot(ev.pos.x - this.pos.x, ev.pos.z - this.pos.z);
        if (d < 18 + 118 * ev.strength) {
          ev.heard = true;
          this.hear(ev.pos, ev.strength, game);
        }
      }
    }
    // near breathing detection, even when still
    if (dist < (player.crouchBlend > .5 ? 5.5 : 3.1) + (this.enraged ? 3 : 0) && player.health > 0) {
      this.lastHeard.copy(player.pos);
      this.lastHeardAge = 0;
      if (this.state !== 'hunt') {
        this.state = 'hunt'; this.stateTime = 0;
        if (game) { this.roar(game, dist); game.onMonsterAlert?.(); }
      }
    }

    if (this.state === 'hunt') {
      if (this.lastHeardAge < 1.15) {
        // pursue predicted player position with slight auditory error
        this.lastHeard.lerp(new THREE.Vector3(player.pos.x, 0, player.pos.z), Math.min(1, dt * (this.enraged ? 4.2 : 2.8)));
      } else {
        this.state = 'search';
        this.stateTime = 0;
        this.searchTimer = 7 + Math.random() * 4;
      }
    } else if (this.state === 'search') {
      this.searchTimer -= dt;
      if (this.searchTimer <= 0 || this.lastHeardAge > 14) {
        this.state = 'wander';
        this.stateTime = 0;
        this.wanderTimer = 0;
        this.wanderTarget = this.pickWanderTarget(this.pos);
      }
    } else {
      // wander
      this.wanderTimer -= dt;
      const dTarget = Math.hypot(this.wanderTarget.x - this.pos.x, this.wanderTarget.z - this.pos.z);
      if (dTarget < 4 || this.wanderTimer <= 0) {
        this.wanderTarget = this.pickWanderTarget(this.pos);
        this.wanderTimer = 11 + Math.random() * 16;
      }
    }

    // choose a movement target
    let target = this.wanderTarget;
    let desiredSpeed = 1.9;
    if (this.state === 'hunt') {
      target = this.lastHeard;
      desiredSpeed = this.maxSpeed;
      if (this.lastHeardAge > 2.5) desiredSpeed = this.maxSpeed * .55;
    } else if (this.state === 'search') {
      target = this.lastHeard;
      const dT = Math.hypot(target.x - this.pos.x, target.z - this.pos.z);
      if (dT < 3.5) {
        // circle / sniff around the last heard point
        const ang = time * .7 + this.phase;
        target = new THREE.Vector3(this.lastHeard.x + Math.cos(ang) * 4.5, 0, this.lastHeard.z + Math.sin(ang) * 4.5);
        desiredSpeed = 2.2;
      } else desiredSpeed = 4.2;
    }

    const dx = target.x - this.pos.x, dz = target.z - this.pos.z;
    const targetYaw = Math.atan2(dx, dz);
    const diff = wrapAngle(targetYaw - this.yaw);
    const speedRatio = clamp(this.speed / this.maxSpeed, 0, 1);
    // 50% turning resistance: high speed = wide sweeps
    const turnRate = (1.85 - speedRatio * 1.23) * (this.enraged ? 1.08 : 1);
    this.yaw += clamp(diff, -turnRate * dt, turnRate * dt);
    // slow down to turn
    if (Math.abs(diff) > 1.2 && this.speed > 4) desiredSpeed *= .55;

    this.speed = damp(this.speed, desiredSpeed, desiredSpeed > this.speed ? 2.2 : 4.5, dt);
    const step = this.speed * dt;
    const prevX = this.pos.x, prevZ = this.pos.z;
    this.pos.x += Math.sin(this.yaw) * step;
    this.pos.z += Math.cos(this.yaw) * step;

    // obstacle avoidance by probing ahead
    const probe = new THREE.Vector3(this.pos.x + Math.sin(this.yaw) * (1.4 + this.speed * .18), 0, this.pos.z + Math.cos(this.yaw) * (1.4 + this.speed * .18));
    const test = probe.clone();
    const blocked = this.world.resolveCollisions(test, this.radius);
    if (blocked) {
      const side = Math.sin(time * 2.1 + this.phase) > 0 ? 1 : -1;
      this.yaw += side * 1.9 * dt;
      this.pos.x -= Math.sin(this.yaw) * step * .2;
      this.pos.z -= Math.cos(this.yaw) * step * .2;
    }
    this.world.resolveCollisions(this.pos, this.radius);
    const actual = Math.hypot(this.pos.x - prevX, this.pos.z - prevZ);

    const threat = m.threat;
    this.dom.threatBars.forEach((el, i) => {
      const on = i < Math.round(threat * 8);
      el.classList.toggle('on', on);
      el.style.height = on ? (5 + i * 1.15) + 'px' : '3px';
    });
    const hot = threat > .48;
