    const z = pos.z - Math.cos(yaw) * 1.1 + (Math.random() - .5) * 1.2;
    this.emit(x, pos.y + .5 + Math.random() * 1.9, z, 0x88c45c, { count: 2, speed: .22, up: .3, spread: 1, life: 1.8, grav: .02, drag: .99 });
  }
  steam(pos, count = 6, color = 0xa8bcac) {
