        }
        arr[i * 6] = d.x; arr[i * 6 + 1] = d.y; arr[i * 6 + 2] = d.z;
        arr[i * 6 + 3] = d.x - .04; arr[i * 6 + 4] = d.y - d.len; arr[i * 6 + 5] = d.z;
      }
      this.rainGeo.attributes.position.needsUpdate = true;
    }
  }
